//! Fast opcode-switch interpreter for gp64
//!
//! This crate provides a fast interpreter that dispatches instructions via a direct
//! opcode switch table, avoiding the overhead of `iced-x86` decode for common opcodes.
//! FPU instructions (D8-DF) use a byte-validated portable x87 decode cache and
//! delegate to the FPU module.
//! Unrecognised opcodes raise #UD (vector 6), matching real hardware behavior.
#![cfg_attr(coverage_nightly, feature(coverage_attribute))]
use gp64_disasm::{instruction_length, Bitness, DecodeError, MAX_INSTRUCTION_LEN};
use std::cell::{Cell, RefCell};
use std::collections::{HashMap, VecDeque};
use std::fs;
use std::path::Path;
use std::ptr;
use std::sync::atomic::{AtomicBool, AtomicU32, AtomicU64, AtomicUsize, Ordering};
use std::sync::{Mutex, OnceLock};
use std::time::Instant;
#[cfg(feature = "arm_call_trace")]
mod arm_call_trace {
    use std::sync::atomic::{AtomicBool, Ordering};
    /// All B1–B8 outlined arms, in source order. Adding a new outlined `op_*`
    /// without extending this list (and adding `record_called(IDX_…)` at the
    /// function's top) will cause the harness `test_outlined_arms_called` to
    /// fail loudly when the new arm is actually entered.
    pub const ARM_NAMES: &[&str] = &[
        "op_bcd",
        "op_aam_aad",
        "op_grp3",
        "op_0f",
        "op_fpu_esc",
        "op_pusha_popa",
        "op_enter",
        "op_les_lds",
        "op_in_out",
        "op_lods",
        "op_scas",
        "op_cmps",
        "op_stos",
        "op_movs",
        "op_ins_outs",
        "op_far_call",
        "op_far_jmp",
        "op_retf",
        "op_iret",
        "op_int_n",
        "op_int3_into_icebp",
    ];
    pub const IDX_OP_BCD: usize = 0;
    pub const IDX_OP_AAM_AAD: usize = 1;
    pub const IDX_OP_GRP3: usize = 2;
    pub const IDX_OP_0F: usize = 3;
    pub const IDX_OP_FPU_ESC: usize = 4;
    pub const IDX_OP_PUSHA_POPA: usize = 5;
    pub const IDX_OP_ENTER: usize = 6;
    pub const IDX_OP_LES_LDS: usize = 7;
    pub const IDX_OP_IN_OUT: usize = 8;
    pub const IDX_OP_LODS: usize = 9;
    pub const IDX_OP_SCAS: usize = 10;
    pub const IDX_OP_CMPS: usize = 11;
    pub const IDX_OP_STOS: usize = 12;
    pub const IDX_OP_MOVS: usize = 13;
    pub const IDX_OP_INS_OUTS: usize = 14;
    pub const IDX_OP_FAR_CALL: usize = 15;
    pub const IDX_OP_FAR_JMP: usize = 16;
    pub const IDX_OP_RETF: usize = 17;
    pub const IDX_OP_IRET: usize = 18;
    pub const IDX_OP_INT_N: usize = 19;
    pub const IDX_OP_INT3_INTO_ICEBP: usize = 20;
    pub const ARM_COUNT: usize = 21;
    pub static CALLED: [AtomicBool; ARM_COUNT] = [
        AtomicBool::new(false),
        AtomicBool::new(false),
        AtomicBool::new(false),
        AtomicBool::new(false),
        AtomicBool::new(false),
        AtomicBool::new(false),
        AtomicBool::new(false),
        AtomicBool::new(false),
        AtomicBool::new(false),
        AtomicBool::new(false),
        AtomicBool::new(false),
        AtomicBool::new(false),
        AtomicBool::new(false),
        AtomicBool::new(false),
        AtomicBool::new(false),
        AtomicBool::new(false),
        AtomicBool::new(false),
        AtomicBool::new(false),
        AtomicBool::new(false),
        AtomicBool::new(false),
        AtomicBool::new(false),
    ];
    const _: () = assert!(
        ARM_NAMES.len() == ARM_COUNT,
        "arm_call_trace::ARM_NAMES len must equal ARM_COUNT"
    );
    const _: () = assert!(
        CALLED.len() == ARM_COUNT,
        "arm_call_trace::CALLED len must equal ARM_COUNT"
    );
    const _: () = assert!(
        IDX_OP_INT3_INTO_ICEBP + 1 == ARM_COUNT,
        "the last index must equal ARM_COUNT - 1 (no gaps)"
    );
    /// Record that the outlined arm at `idx` has been entered. Hot-path cost
    /// after the first call is a single relaxed load + early return; on the
    /// first call it's the load + a relaxed store (a one-shot transition).
    #[inline]
    pub fn record_called(idx: usize) {
        if !CALLED[idx].load(Ordering::Relaxed) {
            CALLED[idx].store(true, Ordering::Relaxed);
        }
    }
    /// Reset all slots — used by tests that run multiple sub-campaigns and
    /// want a clean baseline. Not used by production code.
    pub fn reset() {
        for slot in CALLED.iter() {
            slot.store(false, Ordering::Relaxed);
        }
    }
    /// Names of every arm that has been called at least once since process
    /// start (or last `reset()`), in source order.
    pub fn dump_called() -> Vec<&'static str> {
        ARM_NAMES
            .iter()
            .zip(CALLED.iter())
            .filter_map(|(name, slot)| {
                if slot.load(Ordering::Relaxed) {
                    Some(*name)
                } else {
                    None
                }
            })
            .collect()
    }
    /// Names of every arm that has NOT been called since process start (or
    /// last `reset()`), in source order. The complement of `dump_called`.
    pub fn dump_uncalled() -> Vec<&'static str> {
        ARM_NAMES
            .iter()
            .zip(CALLED.iter())
            .filter_map(|(name, slot)| {
                if slot.load(Ordering::Relaxed) {
                    None
                } else {
                    Some(*name)
                }
            })
            .collect()
    }
}
