mod cr0_x87_gate_tests;
/// Milestone-Q Q0.1 (HLD 2026.07.09 §4.1): count of D8–DF FPU escapes
/// dispatched by the interpreter. This diagnostic is part of the default-off
/// `interp-attrib` feature: production builds compile the note site away.
pub mod fpu_stats {
    #[cfg(feature = "interp-attrib")]
    use std::sync::atomic::{AtomicU64, Ordering::Relaxed};
    #[cfg(feature = "interp-attrib")]
    static DISPATCHED: AtomicU64 = AtomicU64::new(0);
    /// One non-`#NM` D8-DF escape was dispatched (counted at the escape
    /// arm, BEFORE the inline lane probes — so lane-admitted escapes are
    /// included; the population is identical to the pre-IQ011 "entered
    /// op_fpu_esc" meaning, when that call was unconditional).
    #[inline(always)]
    pub(crate) fn note_dispatched() {
        #[cfg(feature = "interp-attrib")]
        DISPATCHED.fetch_add(1, Relaxed);
    }
    /// Cumulative dispatched-escape count, or zero when attribution is off.
    #[must_use]
    #[inline(always)]
    pub fn dispatched() -> u64 {
        #[cfg(feature = "interp-attrib")]
        {
            DISPATCHED.load(Relaxed)
        }
        #[cfg(not(feature = "interp-attrib"))]
        {
            0
        }
    }
    #[cfg(all(test, feature = "interp-attrib"))]
    mod tests {
        #[test]
        fn note_dispatched_is_monotonic() {
            let before = super::dispatched();
            super::note_dispatched();
            super::note_dispatched();
            assert!(super::dispatched() >= before + 2);
        }
    }
}
