#[derive(Clone, Copy, Debug, Default)]
struct InterpChargeSnapshot {
    charged_cycles: u32,
    charged_retired: u32,
    charged_video_writes: u64,
}
struct ChargedCycleRecorder {
    charged_cycles: *const u32,
    charged_retired: *const u32,
    charged_video_writes: *const u64,
}
impl ChargedCycleRecorder {
    fn new(charged_cycles: &u32, charged_retired: &u32, charged_video_writes: &u64) -> Self {
        LAST_INTERP_CHARGE.with(|last| last.set(InterpChargeSnapshot::default()));
        Self {
            charged_cycles,
            charged_retired,
            charged_video_writes,
        }
    }
}
impl Drop for ChargedCycleRecorder {
    fn drop(&mut self) {
        let snapshot = InterpChargeSnapshot {
            charged_cycles: unsafe { *self.charged_cycles },
            charged_retired: unsafe { *self.charged_retired },
            charged_video_writes: unsafe { *self.charged_video_writes },
        };
        LAST_INTERP_CHARGE.with(|last| last.set(snapshot));
    }
}
#[inline]
fn last_interp_charge() -> InterpChargeSnapshot {
    LAST_INTERP_CHARGE.with(Cell::get)
}
#[inline]
fn charged_elements(count: u32, cost: u32) -> u32 {
    count.saturating_mul(cost)
}
#[inline]
#[allow(dead_code)]
fn bit_scan_charged_cycles(
    cpu_type: gp64_cpu::CpuType,
    reverse: bool,
    op_size_32: bool,
    src: u32,
    memory_operand: bool,
) -> u32 {
    if !cpu_type.supports_pentium() {
        return NORMAL_INSTRUCTION_CHARGED_CYCLES;
    }
    let bits: u32 = if op_size_32 { 32 } else { 16 };
    let scan_distance = if src == 0 {
        bits
    } else if reverse {
        let bit = src.ilog2();
        (bits - 1).saturating_sub(bit)
    } else {
        src.trailing_zeros()
    };
    let cycles = 7 + scan_distance * 2;
    cycles + u32::from(memory_operand)
}
