static FAST_0F_UD_DUMPED: AtomicBool = AtomicBool::new(false);
#[derive(Clone, Copy)]
struct InterpTraceRecord {
    cs: u16,
    ip: u16,
    prev_cs: u16,
    prev_ip: u16,
    bytes: [u8; TRACE_BYTES_LEN],
    ax: u16,
    bx: u16,
    cx: u16,
    dx: u16,
    si: u16,
    di: u16,
    bp: u16,
    ds: u16,
    es: u16,
    ss: u16,
    sp: u16,
}
impl InterpTraceRecord {
    fn capture(
        fetch_base: *const u8,
        pos_start: usize,
        trace_cs: u16,
        trace_ip: u16,
        prev_cs: u16,
        prev_ip: u16,
        regs: &gp64_cpu::Registers,
    ) -> Self {
        let mut bytes = [0u8; TRACE_BYTES_LEN];
        unsafe {
            ptr::copy_nonoverlapping(fetch_base.add(pos_start), bytes.as_mut_ptr(), bytes.len());
        }
        Self {
            cs: trace_cs,
            ip: trace_ip,
            prev_cs,
            prev_ip,
            bytes,
            ax: regs.ax(),
            bx: regs.bx(),
            cx: regs.cx(),
            dx: regs.dx(),
            si: regs.si(),
            di: regs.di(),
            bp: regs.bp(),
            ds: regs.ds,
            es: regs.es,
            ss: regs.ss,
            sp: regs.sp(),
        }
    }
}
fn stack_linear_trace_range_cfg() -> Option<(u32, u32)> {
    None
}
#[inline]
fn maybe_trace_stack_linear_access(
    kind: &'static str,
    cpu: &Cpu,
    linear: u32,
    phys: usize,
    width: u8,
    value: u64,
) {
    let Some((range_start, range_end)) = stack_linear_trace_range_cfg() else {
        return;
    };
    let access_end = linear.wrapping_add(width as u32);
    if access_end <= range_start || linear >= range_end {
        return;
    }
    tracing::info!(
        target : "gp64::diag::stack_linear_access", kind, cs = format_args!("{:04X}", cpu
        .regs.cs), eip = format_args!("{:08X}", cpu.regs.eip), ss =
        format_args!("{:04X}", cpu.regs.ss), esp = format_args!("{:08X}", cpu.regs.esp),
        linear = format_args!("{:08X}", linear), phys = format_args!("{:08X}", phys),
        width, value = format_args!("{:016X}", value), eax = format_args!("{:08X}", cpu
        .regs.eax), ebx = format_args!("{:08X}", cpu.regs.ebx), ecx =
        format_args!("{:08X}", cpu.regs.ecx), edx = format_args!("{:08X}", cpu.regs.edx),
        ebp = format_args!("{:08X}", cpu.regs.ebp), "stack linear access"
    );
}
#[cfg_attr(test, allow(dead_code))]
struct InterpStepTraceState {
    cfg: OnceLock<Option<InterpTraceAtCfg>>,
    int_cfg: OnceLock<Option<u8>>,
    step_init: OnceLock<u64>,
    enabled: OnceLock<bool>,
    record_trace_enabled: OnceLock<bool>,
    backlog_cap: OnceLock<usize>,
    backlog: OnceLock<Mutex<VecDeque<InterpTraceRecord>>>,
    triggered: AtomicBool,
    rem: AtomicU64,
    step_started: AtomicBool,
    step_rem: AtomicU64,
}
impl InterpStepTraceState {
    const fn new() -> Self {
        Self {
            cfg: OnceLock::new(),
            int_cfg: OnceLock::new(),
            step_init: OnceLock::new(),
            enabled: OnceLock::new(),
            record_trace_enabled: OnceLock::new(),
            backlog_cap: OnceLock::new(),
            backlog: OnceLock::new(),
            triggered: AtomicBool::new(false),
            rem: AtomicU64::new(0),
            step_started: AtomicBool::new(false),
            step_rem: AtomicU64::new(0),
        }
    }
    /// Post-trigger step count shared by all trigger modes (CS:IP and int-vector).
    /// Formerly read from a (retired) env var, default 0.
    fn post_trigger_count() -> u64 {
        0
    }
    /// Resolve the configured backlog capacity. The former env override was retired
    /// so this always resolves to the default capacity.
    fn backlog_cap(&self) -> usize {
        *self.backlog_cap.get_or_init(interp_read_backlog_capacity)
    }
    fn trace_at_should_log(
        &self,
        cfg: Option<InterpTraceAtCfg>,
        trace_cs: u16,
        trace_ip: u16,
    ) -> (bool, bool) {
        let mut just_triggered = false;
        if let Some(cfg) = cfg {
            if trace_cs == cfg.cs
                && trace_ip == cfg.ip
                && !self.triggered.load(Ordering::Relaxed)
                && self.rem.load(Ordering::Relaxed) == 0
            {
                self.rem.store(cfg.n, Ordering::Relaxed);
                self.triggered.store(true, Ordering::Relaxed);
                just_triggered = true;
            }
            if self.rem.load(Ordering::Relaxed) > 0 {
                self.rem.fetch_sub(1, Ordering::Relaxed);
                return (just_triggered, true);
            }
        }
        (false, false)
    }
    fn step_should_log(&self, init: u64) -> bool {
        if init == 0 {
            return false;
        }
        if !self.step_started.swap(true, Ordering::Relaxed) {
            self.step_rem.store(init, Ordering::Relaxed);
        }
        if self.step_rem.load(Ordering::Relaxed) > 0 {
            self.step_rem.fetch_sub(1, Ordering::Relaxed);
            return true;
        }
        false
    }
    fn backlog(&self) -> &Mutex<VecDeque<InterpTraceRecord>> {
        let cap = self.backlog_cap();
        self.backlog
            .get_or_init(|| Mutex::new(VecDeque::with_capacity(cap)))
    }
    fn push_backlog(&self, record: InterpTraceRecord) {
        let cap = self.backlog_cap();
        let mut backlog = self
            .backlog()
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if backlog.len() == cap {
            backlog.pop_front();
        }
        backlog.push_back(record);
    }
    fn drain_backlog(&self) -> Vec<InterpTraceRecord> {
        let mut backlog = self
            .backlog()
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        backlog.drain(..).collect()
    }
    fn snapshot_backlog(&self, limit: usize) -> Vec<InterpTraceRecord> {
        let backlog = self
            .backlog()
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let take = limit.min(backlog.len());
        backlog
            .iter()
            .skip(backlog.len().saturating_sub(take))
            .copied()
            .collect()
    }
    #[cfg(test)]
    fn clear_backlog_for_test(&self) {
        if let Some(backlog) = self.backlog.get() {
            backlog
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .clear();
        }
        self.triggered.store(false, Ordering::Relaxed);
        self.rem.store(0, Ordering::Relaxed);
        self.step_started.store(false, Ordering::Relaxed);
        self.step_rem.store(0, Ordering::Relaxed);
    }
    /// Notify that the emulator is about to dispatch an interrupt with the
    /// given vector. If the interrupt-vector trigger matches and we're not
    /// already triggered, drain the backlog as `TRACE_PREV` records and arm
    /// the post-trigger counter. One-shot: subsequent matching calls are
    /// no-ops. Cheap no-op when the int trigger is unconfigured.
    ///
    /// Reads `self.int_cfg` directly (no env-var access). The global public
    /// entry point `notify_interrupt_dispatch` lazily initializes `int_cfg`
    /// from a (retired) env var before delegating here.
    #[cold]
    fn notify_interrupt(&self, vector: u8) {
        let Some(cfg_vector) = self.int_cfg.get().copied().flatten() else {
            return;
        };
        if cfg_vector != vector {
            return;
        }
        if self.triggered.swap(true, Ordering::Relaxed) {
            return;
        }
        self.rem
            .store(Self::post_trigger_count(), Ordering::Relaxed);
        for prev_record in self.drain_backlog() {
            log_interp_step_trace_record("TRACE_PREV", &prev_record);
        }
    }
}
