#[cfg(test)]
fn parse_interp_eip_range_spec(raw: &str) -> Option<(u32, u32)> {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return None;
    }
    let (start_raw, end_raw) = trimmed.split_once(':')?;
    let start_raw = start_raw
        .trim()
        .trim_start_matches("0x")
        .trim_start_matches("0X");
    let end_raw = end_raw
        .trim()
        .trim_start_matches("0x")
        .trim_start_matches("0X");
    let start = u32::from_str_radix(start_raw, 16).ok()?;
    let end = u32::from_str_radix(end_raw, 16).ok()?;
    (start <= end).then_some((start, end))
}
