fn parse_interp_eip_range_cs_spec(raw: &str) -> Option<u16> {
    let trimmed = raw.trim().trim_start_matches("0x").trim_start_matches("0X");
    if trimmed.is_empty() {
        return None;
    }
    u16::from_str_radix(trimmed, 16).ok()
}
