        for i in 0..instr_len {
            if i > 0 {
                instr_hex.push(' ');
            }
            let b = unsafe { read_u8_fast(fetch_base, pos_start + i) };
            use std::fmt::Write;
            let _ = write!(instr_hex, "{b:02X}");
        }
        instr_hex
