/// Compile-time master switch for the hot-path diagnostic surface
/// (2026.07.30 emu_probes HLD). `any(test, ...)` keeps unit tests exercising
/// probe paths; root integration tests enable the feature via the root
/// dev-dependency. When false, `diag_active` and every `EMU_PROBES &&`
/// conjunction fold to constant false and the optimiser deletes the guarded
/// diagnostic envelope from the interpreter loop.
pub const EMU_PROBES: bool = cfg!(any(test, feature = "emu_probes"));
/// True when this build carries the diagnostic surface (the `emu_probes`
/// feature proper — deliberately NOT `any(test, ...)`). CLI flags that
/// require diagnostics consult this to fail loudly on a normal build.
pub const fn probes_compiled() -> bool {
    cfg!(feature = "emu_probes")
}
static WATCHPOINTS_ENABLED: AtomicBool = AtomicBool::new(false);
/// Enable or disable per-instruction watchpoint stores (INTERP_WATCHPOINT_*).
/// The watchdog should call `enable_watchpoints(true)` before starting.
pub fn enable_watchpoints(enabled: bool) {
    WATCHPOINTS_ENABLED.store(enabled, Ordering::Relaxed);
}
/// Result of running the fast interpreter for a budget of instructions.
///
/// Every variant carries an `executed` count so the caller can update cycle
/// accounting regardless of why the loop exited.
#[derive(Debug, Clone)]
pub enum RunResult {
    /// Budget fully consumed — the caller should do maintenance and re-enter.
    BudgetExhausted { executed: u32 },
    /// An instruction opened an interrupt-recognition boundary. The caller must
    /// poll before executing another unshadowed instruction.
    InterruptPollBoundary { executed: u32 },
    /// HLT instruction executed.
    Halt { executed: u32 },
    /// Software interrupt (INT n) — the caller dispatches via the IVT / HLE table.
    SoftwareInterrupt { vector: u8, executed: u32 },
    /// CPU exception (GP#, UD#, etc.) with optional fault address.
    Exception {
        vector: u8,
        error_code: u32,
        fault_addr: Option<u32>,
        executed: u32,
    },
    /// CS:IP points into an HLE segment (BIOS F000:xxxx) — hand off to HLE handler.
    HleEntry { executed: u32 },
    /// An I/O instruction (IN/OUT) completed — the caller may need to check devices.
    IoCompleted { executed: u32 },
    /// IRET executed — the caller may need to check for nested interrupt returns.
    Iret { executed: u32 },
    /// Far return (RETF) executed.
    Retf { executed: u32 },
    /// IRETD detected a V86 mode switch — the caller handles via HLE.
    V86Switch {
        frame: gp64_cpu::V86SwitchFrame,
        executed: u32,
    },
    /// A script sentinel address was hit (used by conformance tests).
    ScriptSentinel { executed: u32 },
    /// MOV CR0 or LMSW changed the PE bit — caller must immediately re-enter
    /// run() to refresh stale locals (cs_bits, pm, cpl3, segment bases).
    /// Do NOT deliver interrupts between this return and re-entry.
    ModeChange { executed: u32 },
    /// INVLPG executed — caller invalidates JIT blocks on the affected page
    /// before re-entering, preventing stale compiled code after page remapping.
    Invlpg { linear_addr: u32, executed: u32 },
    /// IRET with NT=1 detected — the caller performs a hardware task switch.
    TaskSwitch { executed: u32 },
    /// JMP FAR targeted a TSS descriptor — emulator performs task switch (JMP)
    TaskSwitchJmp { selector: u16, executed: u32 },
    /// CALL FAR targeted a TSS descriptor — emulator performs task switch (CALL)
    TaskSwitchCall { selector: u16, executed: u32 },
    /// CALL FAR targeted a call gate descriptor — emulator performs gate transition
    CallGate {
        selector: u16,
        return_cs: u16,
        return_eip: u32,
        executed: u32,
    },
}
#[derive(Debug, Clone)]
pub struct ChargedRunResult {
    pub result: RunResult,
    pub charged_cycles: u32,
}
impl RunResult {
    /// Return the number of instructions executed before this exit, regardless
    /// of the exit reason.
    #[inline]
    pub fn executed(&self) -> u32 {
        match self {
            Self::BudgetExhausted { executed }
            | Self::InterruptPollBoundary { executed }
            | Self::Halt { executed }
            | Self::SoftwareInterrupt { executed, .. }
            | Self::Exception { executed, .. }
            | Self::HleEntry { executed }
            | Self::IoCompleted { executed }
            | Self::Iret { executed }
            | Self::Retf { executed }
            | Self::V86Switch { executed, .. }
            | Self::ScriptSentinel { executed }
            | Self::ModeChange { executed }
            | Self::Invlpg { executed, .. }
            | Self::TaskSwitch { executed }
            | Self::TaskSwitchJmp { executed, .. }
            | Self::TaskSwitchCall { executed, .. }
            | Self::CallGate { executed, .. } => *executed,
        }
    }
    #[inline]
    pub fn legacy_cycle_count(&self) -> u32 {
        match self {
            Self::SoftwareInterrupt { executed, .. }
            | Self::Exception { executed, .. }
            | Self::Iret { executed }
            | Self::Retf { executed }
            | Self::V86Switch { executed, .. }
            | Self::ModeChange { executed }
            | Self::Invlpg { executed, .. } => {
                executed.saturating_add(NORMAL_INSTRUCTION_CHARGED_CYCLES)
            }
            _ => self.executed(),
        }
    }
    #[inline]
    fn charged_retired_floor(&self) -> u32 {
        match self {
            Self::Exception { executed, .. } => {
                executed.saturating_add(NORMAL_INSTRUCTION_CHARGED_CYCLES)
            }
            _ => self.executed(),
        }
    }
}
#[inline]
fn data_segment_load_exception(err: CpuError, selector: u16, executed: u32) -> RunResult {
    match err {
        CpuError::SegmentNotPresent(sel) => RunResult::Exception {
            vector: 11,
            error_code: (sel & 0xFFFC) as u32,
            fault_addr: None,
            executed,
        },
        CpuError::PageFault(info) => RunResult::Exception {
            vector: 14,
            error_code: info.error_code,
            fault_addr: Some(info.linear_address),
            executed,
        },
        _ => RunResult::Exception {
            vector: 13,
            error_code: (selector & 0xFFFC) as u32,
            fault_addr: None,
            executed,
        },
    }
}
#[inline]
/// Classify a failure to pop RETF's return frame off the current stack.
///
/// The `#SS` error code is **always 0** here, and deliberately not a parameter
/// Every `StackFault` this helper can see comes from
/// `try_pop16`/`try_pop32` failing their `stack_range_ok` check — a stack-segment
/// LIMIT violation, which involves no selector, and for which the SDM specifies
/// error code 0. The selector-bearing `#SS` cases are raised by `load_ss` on a
/// different path and never arrive here.
///
/// This used to take a `stack_error_code`, and all 16 call sites passed
/// `cpu.last_exception_error_code` — a field nothing on the pop path ever writes,
/// so a genuine limit violation reported whatever stale selector code an earlier
/// segment load had left behind. Taking the value as a parameter is what made
/// that possible; keeping it out is the fix.
fn retf_stack_pop_exception(err: CpuError, executed: u32) -> RunResult {
    match err {
        CpuError::PageFault(info) => RunResult::Exception {
            vector: 14,
            error_code: info.error_code,
            fault_addr: Some(info.linear_address),
            executed,
        },
        CpuError::StackFault => RunResult::Exception {
            vector: 12,
            error_code: 0,
            fault_addr: None,
            executed,
        },
        _ => RunResult::Exception {
            vector: 13,
            error_code: 0,
            fault_addr: None,
            executed,
        },
    }
}
#[inline]
fn far_cs_load_exception(err: CpuError, gp_error_code: u32, executed: u32) -> RunResult {
    match err {
        CpuError::SegmentNotPresent(selector) => RunResult::Exception {
            vector: 11,
            error_code: (selector & 0xFFFC) as u32,
            fault_addr: None,
            executed,
        },
        CpuError::PageFault(info) => RunResult::Exception {
            vector: 14,
            error_code: info.error_code,
            fault_addr: Some(info.linear_address),
            executed,
        },
        _ => RunResult::Exception {
            vector: 13,
            error_code: gp_error_code,
            fault_addr: None,
            executed,
        },
    }
}
/// Even-parity lookup table: `PARITY_TABLE[byte]` is `true` if `byte` has an
/// even number of set bits.
static PARITY_TABLE: [bool; 256] = {
    let mut table = [false; 256];
    let mut i = 0u16;
    while i < 256 {
        table[i as usize] = (i.count_ones() & 1) == 0;
        i += 1;
    }
    table
};
#[derive(Clone, Copy, Debug, PartialEq)]
enum RepPrefix {
    None,
    Rep,
    Repne,
}
/// Cheap admission guard before the iced SIMD decoder. Mandatory-prefix SIMD
/// can overlap ordinary 0F and MMX encodings, while unprefixed SSE occupies a
/// small fixed set of rows. False positives are safe: semantic classification
/// rejects them and the compact switch below remains authoritative.
#[inline]
fn may_be_legacy_simd(opcode: u8, mandatory_prefix: bool) -> bool {
    mandatory_prefix
        || matches!(
            opcode, 0x10..= 0x18 | 0x28..= 0x2F | 0x50..= 0x5F | 0x70 | 0xAE | 0xC2..=
            0xC6 | 0xD4 | 0xD7 | 0xDA | 0xDE | 0xE0 | 0xE3..= 0xE4 | 0xE7..= 0xE8 | 0xEA
            | 0xEE | 0xF4 | 0xF6..= 0xF7 | 0xFB
        )
}
/// Return a bitset for the SIMD mandatory prefixes present in the consumed
/// prefix run: bit 0 = 66, bit 1 = F2, bit 2 = F3. This is only an admission
/// hint; precedence between multiple mandatory prefixes is decided by the
/// decoder itself (`sse_decode::Prefixes::class`).
#[inline]
unsafe fn simd_mandatory_prefix_mask(
    fetch_base: *const u8,
    pos_start: usize,
    opcode_0f_pos: usize,
) -> u8 {
    let mut mask = 0u8;
    let mut position = pos_start;
    while position < opcode_0f_pos {
        match unsafe { read_u8_fast(fetch_base, position) } {
            0x66 => mask |= 1,
            0xF2 => mask |= 2,
            0xF3 => mask |= 4,
            _ => {}
        }
        position += 1;
    }
    mask
}
/// Hot register-register SSE2 integer forms. Keeping these fixed-width
/// operations beside the interpreter avoids constructing an iced instruction
/// for the inner loops that use SIMD as intended.
#[inline]
fn execute_sse2_integer_register(opcode: u8, left: u128, right: u128) -> Option<u128> {
    macro_rules! packed {
        ($lane:ty, $count:expr, $op:ident) => {{
            let left = left.to_le_bytes();
            let right = right.to_le_bytes();
            let width = core::mem::size_of::<$lane>();
            let mut out = [0u8; 16];
            for lane in 0..$count {
                let a = <$lane>::from_le_bytes(
                    left[lane * width..][..width]
                        .try_into()
                        .expect("lane bytes"),
                );
                let b = <$lane>::from_le_bytes(
                    right[lane * width..][..width]
                        .try_into()
                        .expect("lane bytes"),
                );
                out[lane * width..][..width].copy_from_slice(&a.$op(b).to_le_bytes());
            }
            Some(u128::from_le_bytes(out))
        }};
    }
    match opcode {
        0xFC => packed!(u8, 16, wrapping_add),
        0xFD => packed!(u16, 8, wrapping_add),
        0xFE => packed!(u32, 4, wrapping_add),
        0xD4 => packed!(u64, 2, wrapping_add),
        0xF8 => packed!(u8, 16, wrapping_sub),
        0xF9 => packed!(u16, 8, wrapping_sub),
        0xFA => packed!(u32, 4, wrapping_sub),
        0xFB => packed!(u64, 2, wrapping_sub),
        0xDB => Some(left & right),
        0xEB => Some(left | right),
        0xEF => Some(left ^ right),
        _ => None,
    }
}
#[derive(Clone, Copy)]
enum SegReg {
    ES,
    CS,
    SS,
    DS,
    FS,
    GS,
}
/// Packed interpreter boolean/counter/enum state in a single `u64`.
///
/// Bit layout:
/// ```text
/// Bits  0-12:  remaining          (u13, max 8191; budget ≤ 4096)
/// Bits 13-25:  executed           (u13, max 8191)
/// Bit     26:  op_size_32
/// Bit     27:  addr_size_32
/// Bit     28:  has_lock
/// Bit     29:  ip_set
/// Bit     30:  seg_dirty
/// Bit     31:  pe_changed
/// Bit     32:  cs_is_32           (mirrors cs_bits == 32)
/// Bits 33-34:  rep_prefix         (0=None, 1=Rep, 2=Repne)
/// Bits 35-38:  seg_override       (0=None, 1-6=ES/CS/SS/DS/FS/GS)
/// Bit     39:  second_page_present
/// Bit     40:  paging
/// Bit     41:  cpl3
/// Bit     42:  wp_enabled
/// ```
#[derive(Clone, Copy)]
#[allow(dead_code)]
struct InterpFlags(u64);
#[allow(dead_code)]
impl InterpFlags {
    const REMAINING_SHIFT: u32 = 0;
    const REMAINING_MASK: u64 = 0x1FFF;
    const EXECUTED_SHIFT: u32 = 13;
    const EXECUTED_MASK: u64 = 0x1FFF << 13;
    const OP_SIZE_32: u64 = 1 << 26;
    const ADDR_SIZE_32: u64 = 1 << 27;
    const HAS_LOCK: u64 = 1 << 28;
    const IP_SET: u64 = 1 << 29;
    const SEG_DIRTY: u64 = 1 << 30;
    const PE_CHANGED: u64 = 1 << 31;
    const CS_IS_32: u64 = 1 << 32;
    const REP_SHIFT: u32 = 33;
    const REP_MASK: u64 = 0x3 << 33;
    const SEG_OVR_SHIFT: u32 = 35;
    const SEG_OVR_MASK: u64 = 0xF << 35;
    const SECOND_PAGE: u64 = 1 << 39;
    const PAGING: u64 = 1 << 40;
    const CPL3: u64 = 1 << 41;
    const WP_ENABLED: u64 = 1 << 42;
    /// Create a new `InterpFlags` with the given initial state.
    ///
    /// Sets `remaining`, `cs_is_32`, `paging`, `cpl3`, `wp_enabled`,
    /// `second_page_present=true`, and derives `op_size_32`/`addr_size_32`
    /// from `cs_is_32`.
    #[inline(always)]
    fn new(remaining: u32, cs_is_32: bool, paging: bool, cpl3: bool, wp_enabled: bool) -> Self {
        let mut v: u64 = (remaining as u64) & 0x1FFF;
        if cs_is_32 {
            v |= Self::CS_IS_32 | Self::OP_SIZE_32 | Self::ADDR_SIZE_32;
        }
        if paging {
            v |= Self::PAGING;
        }
        if cpl3 {
            v |= Self::CPL3;
        }
        if wp_enabled {
            v |= Self::WP_ENABLED;
        }
        v |= Self::SECOND_PAGE;
        Self(v)
    }
    #[inline(always)]
    fn remaining(self) -> u32 {
        (self.0 & Self::REMAINING_MASK) as u32
    }
    #[inline(always)]
    fn executed(self) -> u32 {
        ((self.0 & Self::EXECUTED_MASK) >> Self::EXECUTED_SHIFT) as u32
    }
    #[inline(always)]
    fn op_size_32(self) -> bool {
        (self.0 & Self::OP_SIZE_32) != 0
    }
    #[inline(always)]
    fn addr_size_32(self) -> bool {
        (self.0 & Self::ADDR_SIZE_32) != 0
    }
    #[inline(always)]
    fn has_lock(self) -> bool {
        (self.0 & Self::HAS_LOCK) != 0
    }
    #[inline(always)]
    fn ip_set(self) -> bool {
        (self.0 & Self::IP_SET) != 0
    }
    #[inline(always)]
    fn seg_dirty(self) -> bool {
        (self.0 & Self::SEG_DIRTY) != 0
    }
    #[inline(always)]
    fn pe_changed(self) -> bool {
        (self.0 & Self::PE_CHANGED) != 0
    }
    #[inline(always)]
    fn cs_is_32(self) -> bool {
        (self.0 & Self::CS_IS_32) != 0
    }
    #[inline(always)]
    fn second_page_present(self) -> bool {
        (self.0 & Self::SECOND_PAGE) != 0
    }
    #[inline(always)]
    fn paging(self) -> bool {
        (self.0 & Self::PAGING) != 0
    }
    #[inline(always)]
    fn cpl3(self) -> bool {
        (self.0 & Self::CPL3) != 0
    }
    #[inline(always)]
    fn wp_enabled(self) -> bool {
        (self.0 & Self::WP_ENABLED) != 0
    }
    #[inline(always)]
    fn rep_prefix(self) -> RepPrefix {
        match (self.0 & Self::REP_MASK) >> Self::REP_SHIFT {
            1 => RepPrefix::Rep,
            2 => RepPrefix::Repne,
            _ => RepPrefix::None,
        }
    }
    /// Decode the 4-bit segment override field.
    /// Returns `None` if no override is active, or `Some(idx)` where
    /// `idx` is 0-5 corresponding to ES/CS/SS/DS/FS/GS.
    #[inline(always)]
    fn seg_override(self) -> Option<u8> {
        let raw = ((self.0 & Self::SEG_OVR_MASK) >> Self::SEG_OVR_SHIFT) as u8;
        if raw == 0 {
            None
        } else {
            Some(raw - 1)
        }
    }
    #[inline(always)]
    fn set_op_size_32(&mut self, v: bool) {
        if v {
            self.0 |= Self::OP_SIZE_32;
        } else {
            self.0 &= !Self::OP_SIZE_32;
        }
    }
    #[inline(always)]
    fn toggle_op_size_32(&mut self) {
        self.0 ^= Self::OP_SIZE_32;
    }
    #[inline(always)]
    fn toggle_addr_size_32(&mut self) {
        self.0 ^= Self::ADDR_SIZE_32;
    }
    #[inline(always)]
    fn set_ip_set(&mut self) {
        self.0 |= Self::IP_SET;
    }
    #[inline(always)]
    fn set_has_lock(&mut self) {
        self.0 |= Self::HAS_LOCK;
    }
    #[inline(always)]
    fn set_seg_dirty(&mut self) {
        self.0 |= Self::SEG_DIRTY;
    }
    #[inline(always)]
    fn clear_seg_dirty(&mut self) {
        self.0 &= !Self::SEG_DIRTY;
    }
    #[inline(always)]
    fn set_pe_changed(&mut self) {
        self.0 |= Self::PE_CHANGED;
    }
    #[inline(always)]
    fn set_paging(&mut self, v: bool) {
        if v {
            self.0 |= Self::PAGING;
        } else {
            self.0 &= !Self::PAGING;
        }
    }
    #[inline(always)]
    fn set_cpl3(&mut self, v: bool) {
        if v {
            self.0 |= Self::CPL3;
        } else {
            self.0 &= !Self::CPL3;
        }
    }
    #[inline(always)]
    fn set_wp_enabled(&mut self, v: bool) {
        if v {
            self.0 |= Self::WP_ENABLED;
        } else {
            self.0 &= !Self::WP_ENABLED;
        }
    }
    #[inline(always)]
    fn set_cs_is_32(&mut self, v: bool) {
        if v {
            self.0 |= Self::CS_IS_32;
        } else {
            self.0 &= !Self::CS_IS_32;
        }
    }
    #[inline(always)]
    fn set_second_page_present(&mut self, v: bool) {
        if v {
            self.0 |= Self::SECOND_PAGE;
        } else {
            self.0 &= !Self::SECOND_PAGE;
        }
    }
    #[inline(always)]
    fn set_rep_prefix(&mut self, rp: RepPrefix) {
        let val = match rp {
            RepPrefix::None => 0u64,
            RepPrefix::Rep => 1u64,
            RepPrefix::Repne => 2u64,
        };
        self.0 = (self.0 & !Self::REP_MASK) | (val << Self::REP_SHIFT);
    }
    /// Store a segment override index (0-5 for ES/CS/SS/DS/FS/GS).
    /// Stored as `idx + 1` internally so that 0 means "no override".
    #[inline(always)]
    fn set_seg_override(&mut self, idx: u8) {
        debug_assert!(
            idx < 6,
            "seg_override index must be 0-5 (ES/CS/SS/DS/FS/GS)"
        );
        let raw = (idx as u64 + 1) & 0xF;
        self.0 = (self.0 & !Self::SEG_OVR_MASK) | (raw << Self::SEG_OVR_SHIFT);
    }
    #[inline(always)]
    fn clear_seg_override(&mut self) {
        self.0 &= !Self::SEG_OVR_MASK;
    }
    #[inline(always)]
    fn set_remaining(&mut self, val: u32) {
        self.0 = (self.0 & !Self::REMAINING_MASK) | ((val as u64) & 0x1FFF);
    }
    #[inline(always)]
    fn set_executed(&mut self, val: u32) {
        self.0 =
            (self.0 & !Self::EXECUTED_MASK) | (((val as u64) & 0x1FFF) << Self::EXECUTED_SHIFT);
    }
    /// Decrement the remaining counter by 1.
    /// Panics in debug builds if remaining is already 0.
    #[inline(always)]
    fn decrement_remaining(&mut self) {
        debug_assert!(self.remaining() > 0);
        self.0 -= 1;
    }
    /// Increment the executed counter by 1.
    /// Panics in debug builds if executed is already at max (8191).
    #[inline(always)]
    fn increment_executed(&mut self) {
        debug_assert!(self.executed() < 8191);
        self.0 += 1 << 13;
    }
    /// Reset per-instruction state in the epilogue.
    ///
    /// 1. Clears HAS_LOCK, IP_SET, REP_MASK, SEG_OVR_MASK in one AND.
    /// 2. Sets SECOND_PAGE.
    /// 3. Branchless cs_is_32 → op_size_32 + addr_size_32 replication.
    #[inline(always)]
    fn reset_instruction(&mut self) {
        self.0 &= !(Self::HAS_LOCK | Self::IP_SET | Self::REP_MASK | Self::SEG_OVR_MASK);
        self.0 |= Self::SECOND_PAGE;
        let cs32 = (self.0 >> 32) & 1;
        self.0 = (self.0 & !(Self::OP_SIZE_32 | Self::ADDR_SIZE_32)) | (cs32 << 26) | (cs32 << 27);
    }
    /// Reset per-instruction prefix state WITHOUT touching `second_page_present`.
    ///
    /// Used at the top of the outer loop, where the fetch phase sets
    /// `second_page_present` correctly AFTER this reset.  Using
    /// `reset_instruction()` here would erase the fetch's value.
    #[inline(always)]
    fn reset_prefix_state(&mut self) {
        self.0 &= !(Self::HAS_LOCK | Self::IP_SET | Self::REP_MASK | Self::SEG_OVR_MASK);
        let cs32 = (self.0 >> 32) & 1;
        self.0 = (self.0 & !(Self::OP_SIZE_32 | Self::ADDR_SIZE_32)) | (cs32 << 26) | (cs32 << 27);
    }
}
