#[cfg(all(test, feature = "interp-attrib"))]
#[cfg_attr(coverage_nightly, coverage(off))]
mod attrib_tests {
    use super::test_helpers::setup;
    use super::*;
    #[test]
    fn wr_walk_composition_classifies_the_vga_window_and_fault_buckets() {
        attrib::test_reset();
        attrib::count_wr_walk_dst(Some(0x9FFFF));
        attrib::count_wr_walk_dst(Some(0xA0000));
        attrib::count_wr_walk_dst(Some(0xBFFFF));
        attrib::count_wr_walk_dst(Some(0xC0000));
        attrib::count_wr_walk_dst(None);
        attrib::count_wr_walk_pre(true);
        attrib::count_wr_walk_pre(false);
        let a = attrib::snapshot();
        assert_eq!(a.wr_walk_dst_vga, 2, "0xA0000 and 0xBFFFF are VGA");
        assert_eq!(a.wr_walk_dst_other, 2, "0x9FFFF and 0xC0000 are not");
        assert_eq!(a.wr_walk_fault, 1, "None lands in the fault bucket");
        assert_eq!(a.wr_walk_pre_tag_miss, 1);
        assert_eq!(a.wr_walk_pre_present, 1);
        let report = attrib::render_snapshot();
        assert!(
            report.contains("write-walk composition: dst_vga=2"),
            "report carries the composition line: {report}"
        );
    }
    #[test]
    fn attrib_counts_ops_prefix_mem_and_taken_jcc() {
        attrib::test_reset();
        let (mut cpu, mut mem) = setup(&[
            0xA0, 0x00, 0x02, 0xA2, 0x01, 0x02, 0x66, 0xB8, 0x78, 0x56, 0x34, 0x12, 0x31, 0xC0,
            0x74, 0x00, 0xF4,
        ]);
        let mut io = ();
        let _ = run_ext(&mut cpu, &mut mem, &mut io, 16, false);
        let a = attrib::snapshot();
        assert_eq!(a.op_exec[0xA0], 1, "MOV AL,moffs dispatched once");
        assert_eq!(a.op_exec[0xA2], 1, "MOV moffs,AL dispatched once");
        assert_eq!(
            a.op_exec[0x66], 1,
            "operand-size prefix counted as its own dispatch (== derived prefix_66)"
        );
        assert_eq!(a.op_exec[0xB8], 1, "MOV EAX,imm32 opcode dispatched once");
        assert_eq!(a.op_exec[0x31], 1, "XOR AX,AX dispatched once");
        assert_eq!(a.op_exec[0x74], 1, "JZ dispatched once");
        assert_eq!(a.op_exec[0xF4], 1, "HLT dispatched once");
        assert_eq!(a.near_jcc_taken, 1, "the JZ was taken (ZF set by XOR)");
        assert_eq!(a.mem_rd[0], 1, "one 8-bit data read (MOV AL,[0200])");
        assert_eq!(a.mem_wr[0], 1, "one 8-bit data write (MOV [0201],AL)");
        let dispatches: u64 = a.op_exec.iter().sum();
        assert_eq!(dispatches, 7, "six opcodes plus one prefix byte dispatched");
    }
    #[test]
    fn attrib_rep_stosb_counts_elements() {
        attrib::test_reset();
        let (mut cpu, mut mem) = setup(&[0xB9, 0x03, 0x00, 0xF3, 0xAA, 0xF4]);
        let mut io = ();
        let _ = run_ext(&mut cpu, &mut mem, &mut io, 16, false);
        let a = attrib::snapshot();
        assert_eq!(a.op_exec[0xB9], 1, "MOV CX dispatched once");
        assert_eq!(
            a.op_exec[0xF3], 1,
            "REP prefix counted as its own dispatch (== derived prefix_rep)"
        );
        assert_eq!(a.op_exec[0xAA], 1, "STOSB opcode dispatched once");
        assert_eq!(a.rep_instances, 1, "one string-op instance");
        assert_eq!(a.rep_elements, 3, "three committed elements");
    }
}
