#[inline(always)]
fn seg_base(cpu: &Cpu, reg: SegReg) -> u32 {
    if cpu.regs.is_v86_mode() {
        let val = match reg {
            SegReg::ES => cpu.regs.es,
            SegReg::CS => cpu.regs.cs,
            SegReg::SS => cpu.regs.ss,
            SegReg::DS => cpu.regs.ds,
            SegReg::FS => cpu.regs.fs,
            SegReg::GS => cpu.regs.gs,
        };
        (val as u32) << 4
    } else {
        let (selector, cache) = match reg {
            SegReg::ES => (cpu.regs.es, cpu.regs.es_cache),
            SegReg::CS => (cpu.regs.cs, cpu.regs.cs_cache),
            SegReg::SS => (cpu.regs.ss, cpu.regs.ss_cache),
            SegReg::DS => (cpu.regs.ds, cpu.regs.ds_cache),
            SegReg::FS => (cpu.regs.fs, cpu.regs.fs_cache),
            SegReg::GS => (cpu.regs.gs, cpu.regs.gs_cache),
        };
        if selector != 0 && segment_cache_is_reset_zero_real_mode(cache) {
            (selector as u32) << 4
        } else {
            cache.base
        }
    }
}
