/// ModR/M index → u32 offset from start of Registers GPR region.
const GPR_OFFSETS: [usize; 8] = [0, 2, 3, 1, 7, 6, 4, 5];
/// ModR/M 8-bit index → byte offset from start of Registers GPR region.
/// 0-3 = AL/CL/DL/BL (low byte), 4-7 = AH/CH/DH/BH (byte 1, little-endian).
const REG8_BYTE_OFFSETS: [usize; 8] = [0, 8, 12, 4, 1, 9, 13, 5];
#[inline(always)]
fn get_reg16(cpu: &Cpu, idx: u8) -> u16 {
    unsafe {
        let base = &cpu.regs.eax as *const u32;
        *base.add(GPR_OFFSETS[(idx & 7) as usize]) as u16
    }
}
#[inline(always)]
fn set_reg16(cpu: &mut Cpu, idx: u8, val: u16) {
    let i = (idx & 7) as usize;
    unsafe {
        let base = &mut cpu.regs.eax as *mut u32;
        let ptr = base.add(GPR_OFFSETS[i]);
        *ptr = (*ptr & 0xFFFF_0000) | val as u32;
    }
    if i == 4 {
        cpu.regs.set_sp(val);
    }
}
#[inline(always)]
fn get_reg32(cpu: &Cpu, idx: u8) -> u32 {
    unsafe {
        let base = &cpu.regs.eax as *const u32;
        *base.add(GPR_OFFSETS[(idx & 7) as usize])
    }
}
#[inline(always)]
fn set_reg32(cpu: &mut Cpu, idx: u8, val: u32) {
    let i = (idx & 7) as usize;
    unsafe {
        let base = &mut cpu.regs.eax as *mut u32;
        *base.add(GPR_OFFSETS[i]) = val;
    }
    if i == 4 {
        cpu.regs.set_sp(val as u16);
    }
}
#[allow(dead_code)]
#[inline(always)]
fn get_reg8(cpu: &Cpu, idx: u8) -> u8 {
    unsafe {
        let base = &cpu.regs.eax as *const u32 as *const u8;
        *base.add(REG8_BYTE_OFFSETS[(idx & 7) as usize])
    }
}
#[inline(always)]
fn set_reg8(cpu: &mut Cpu, idx: u8, val: u8) {
    unsafe {
        let base = &mut cpu.regs.eax as *mut u32 as *mut u8;
        *base.add(REG8_BYTE_OFFSETS[(idx & 7) as usize]) = val;
    }
}
/// Get the source index register value based on address size.
#[inline(always)]
fn str_si(cpu: &Cpu, addr32: bool) -> u32 {
    if addr32 {
        cpu.regs.esi
    } else {
        cpu.regs.si() as u32
    }
}
/// Get the destination index register value based on address size.
#[inline(always)]
fn str_di(cpu: &Cpu, addr32: bool) -> u32 {
    if addr32 {
        cpu.regs.edi
    } else {
        cpu.regs.di() as u32
    }
}
/// TF reports a debug boundary after each REP element, including bulk paths.
#[inline(always)]
fn rep_iteration_budget(remaining: u32, flags: Flags) -> u32 {
    if flags.contains(Flags::TRAP) {
        remaining.min(1)
    } else {
        remaining
    }
}

/// Get the count register value based on address size.
#[inline(always)]
fn str_cx(cpu: &Cpu, addr32: bool) -> u32 {
    if addr32 {
        cpu.regs.ecx
    } else {
        cpu.regs.cx() as u32
    }
}
/// Advance SI by delta (positive or negative), using correct register width.
#[inline(always)]
fn str_advance_si(cpu: &mut Cpu, addr32: bool, delta: i32) {
    if addr32 {
        cpu.regs.esi = (cpu.regs.esi as i32).wrapping_add(delta) as u32;
    } else {
        cpu.regs
            .set_si((cpu.regs.si() as i16).wrapping_add(delta as i16) as u16);
    }
}
/// Advance DI by delta (positive or negative), using correct register width.
#[inline(always)]
fn str_advance_di(cpu: &mut Cpu, addr32: bool, delta: i32) {
    if addr32 {
        cpu.regs.edi = (cpu.regs.edi as i32).wrapping_add(delta) as u32;
    } else {
        cpu.regs
            .set_di((cpu.regs.di() as i16).wrapping_add(delta as i16) as u16);
    }
}
/// Set the count register to a value, using correct register width.
#[inline(always)]
fn str_set_cx(cpu: &mut Cpu, addr32: bool, val: u32) {
    if addr32 {
        cpu.regs.ecx = val;
    } else {
        cpu.regs.set_cx(val as u16);
    }
}
/// Deferred ALU flag state. Stores operands so flags are only computed when
/// actually needed (by a Jcc, PUSHF, LAHF, etc.).
///
/// `None` means flags are materialized in `cpu.regs.flags` already.
#[derive(Clone, Copy)]
#[allow(dead_code)]
enum LazyOp {
    None,
    Add8 { a: u8, b: u8, r: u8 },
    Add16 { a: u16, b: u16, r: u16 },
    Add32 { a: u32, b: u32, r: u32 },
    Sub8 { a: u8, b: u8, r: u8 },
    Sub16 { a: u16, b: u16, r: u16 },
    Sub32 { a: u32, b: u32, r: u32 },
    Logic8(u8),
    Logic16(u16),
    Logic32(u32),
    Inc8 { old: u8, r: u8 },
    Inc16 { old: u16, r: u16 },
    Inc32 { old: u32, r: u32 },
    Dec8 { old: u8, r: u8 },
    Dec16 { old: u16, r: u16 },
    Dec32 { old: u32, r: u32 },
    Shift8(u8),
    Shift16(u16),
    Shift32(u32),
}
#[inline(always)]
fn get_cf(flags_reg: Flags, lazy: &LazyOp) -> bool {
    match *lazy {
        LazyOp::None => flags_reg.contains(Flags::CARRY),
        LazyOp::Add8 { a, r, .. } => r < a,
        LazyOp::Add16 { a, r, .. } => r < a,
        LazyOp::Add32 { a, r, .. } => r < a,
        LazyOp::Sub8 { a, b, .. } => a < b,
        LazyOp::Sub16 { a, b, .. } => a < b,
        LazyOp::Sub32 { a, b, .. } => a < b,
        LazyOp::Logic8(_) | LazyOp::Logic16(_) | LazyOp::Logic32(_) => false,
        LazyOp::Inc8 { .. }
        | LazyOp::Inc16 { .. }
        | LazyOp::Inc32 { .. }
        | LazyOp::Dec8 { .. }
        | LazyOp::Dec16 { .. }
        | LazyOp::Dec32 { .. } => flags_reg.contains(Flags::CARRY),
        LazyOp::Shift8(_) | LazyOp::Shift16(_) | LazyOp::Shift32(_) => {
            flags_reg.contains(Flags::CARRY)
        }
    }
}
#[inline(always)]
fn get_zf(flags_reg: Flags, lazy: &LazyOp) -> bool {
    match *lazy {
        LazyOp::None => flags_reg.contains(Flags::ZERO),
        LazyOp::Add8 { r, .. } | LazyOp::Sub8 { r, .. } => r == 0,
        LazyOp::Add16 { r, .. } | LazyOp::Sub16 { r, .. } => r == 0,
        LazyOp::Add32 { r, .. } | LazyOp::Sub32 { r, .. } => r == 0,
        LazyOp::Logic8(r) => r == 0,
        LazyOp::Logic16(r) => r == 0,
        LazyOp::Logic32(r) => r == 0,
        LazyOp::Inc8 { r, .. } | LazyOp::Dec8 { r, .. } => r == 0,
        LazyOp::Inc16 { r, .. } | LazyOp::Dec16 { r, .. } => r == 0,
        LazyOp::Inc32 { r, .. } | LazyOp::Dec32 { r, .. } => r == 0,
        LazyOp::Shift8(r) => r == 0,
        LazyOp::Shift16(r) => r == 0,
        LazyOp::Shift32(r) => r == 0,
    }
}
#[inline(always)]
fn get_sf(flags_reg: Flags, lazy: &LazyOp) -> bool {
    match *lazy {
        LazyOp::None => flags_reg.contains(Flags::SIGN),
        LazyOp::Add8 { r, .. } | LazyOp::Sub8 { r, .. } => r & 0x80 != 0,
        LazyOp::Add16 { r, .. } | LazyOp::Sub16 { r, .. } => r & 0x8000 != 0,
        LazyOp::Add32 { r, .. } | LazyOp::Sub32 { r, .. } => r & 0x8000_0000 != 0,
        LazyOp::Logic8(r) => r & 0x80 != 0,
        LazyOp::Logic16(r) => r & 0x8000 != 0,
        LazyOp::Logic32(r) => r & 0x8000_0000 != 0,
        LazyOp::Inc8 { r, .. } | LazyOp::Dec8 { r, .. } => r & 0x80 != 0,
        LazyOp::Inc16 { r, .. } | LazyOp::Dec16 { r, .. } => r & 0x8000 != 0,
        LazyOp::Inc32 { r, .. } | LazyOp::Dec32 { r, .. } => r & 0x8000_0000 != 0,
        LazyOp::Shift8(r) => r & 0x80 != 0,
        LazyOp::Shift16(r) => r & 0x8000 != 0,
        LazyOp::Shift32(r) => r & 0x8000_0000 != 0,
    }
}
#[inline(always)]
fn get_of(flags_reg: Flags, lazy: &LazyOp) -> bool {
    match *lazy {
        LazyOp::None => flags_reg.contains(Flags::OVERFLOW),
        LazyOp::Add8 { a, b, r } => ((a ^ b ^ 0x80) & (r ^ b)) & 0x80 != 0,
        LazyOp::Add16 { a, b, r } => ((a ^ b ^ 0x8000) & (r ^ b)) & 0x8000 != 0,
        LazyOp::Add32 { a, b, r } => ((a ^ b ^ 0x8000_0000) & (r ^ b)) & 0x8000_0000 != 0,
        LazyOp::Sub8 { a, b, r } => ((a ^ b) & (a ^ r)) & 0x80 != 0,
        LazyOp::Sub16 { a, b, r } => ((a ^ b) & (a ^ r)) & 0x8000 != 0,
        LazyOp::Sub32 { a, b, r } => ((a ^ b) & (a ^ r)) & 0x8000_0000 != 0,
        LazyOp::Logic8(_) | LazyOp::Logic16(_) | LazyOp::Logic32(_) => false,
        LazyOp::Inc8 { r, .. } => r == 0x80,
        LazyOp::Inc16 { r, .. } => r == 0x8000,
        LazyOp::Inc32 { r, .. } => r == 0x8000_0000,
        LazyOp::Dec8 { r, .. } => r == 0x7F,
        LazyOp::Dec16 { r, .. } => r == 0x7FFF,
        LazyOp::Dec32 { r, .. } => r == 0x7FFF_FFFF,
        LazyOp::Shift8(_) | LazyOp::Shift16(_) | LazyOp::Shift32(_) => {
            flags_reg.contains(Flags::OVERFLOW)
        }
    }
}
#[inline(always)]
fn get_af(flags_reg: Flags, lazy: &LazyOp) -> bool {
    match *lazy {
        LazyOp::None => flags_reg.contains(Flags::AUX_CARRY),
        LazyOp::Add8 { a, b, r } => ((a as u16 ^ b as u16) ^ r as u16) & 0x10 != 0,
        LazyOp::Add16 { a, b, r } => ((a ^ b) ^ r) & 0x10 != 0,
        LazyOp::Add32 { a, b, r } => ((a ^ b) ^ r) & 0x10 != 0,
        LazyOp::Sub8 { a, b, r } => ((a as u16 ^ b as u16) ^ r as u16) & 0x10 != 0,
        LazyOp::Sub16 { a, b, r } => ((a ^ b) ^ r) & 0x10 != 0,
        LazyOp::Sub32 { a, b, r } => ((a ^ b) ^ r) & 0x10 != 0,
        LazyOp::Logic8(_) | LazyOp::Logic16(_) | LazyOp::Logic32(_) => false,
        LazyOp::Inc8 { r, .. } => (r & 0x0F) == 0,
        LazyOp::Inc16 { r, .. } => (r as u8 & 0x0F) == 0,
        LazyOp::Inc32 { r, .. } => (r as u8 & 0x0F) == 0,
        LazyOp::Dec8 { r, .. } => (r & 0x0F) == 0x0F,
        LazyOp::Dec16 { r, .. } => (r as u8 & 0x0F) == 0x0F,
        LazyOp::Dec32 { r, .. } => (r as u8 & 0x0F) == 0x0F,
        LazyOp::Shift8(_) | LazyOp::Shift16(_) | LazyOp::Shift32(_) => false,
    }
}
#[inline(always)]
fn get_pf(flags_reg: Flags, lazy: &LazyOp) -> bool {
    match *lazy {
        LazyOp::None => flags_reg.contains(Flags::PARITY),
        LazyOp::Add8 { r, .. } | LazyOp::Sub8 { r, .. } => PARITY_TABLE[r as usize],
        LazyOp::Add16 { r, .. } | LazyOp::Sub16 { r, .. } => PARITY_TABLE[(r & 0xFF) as usize],
        LazyOp::Add32 { r, .. } | LazyOp::Sub32 { r, .. } => PARITY_TABLE[(r & 0xFF) as usize],
        LazyOp::Logic8(r) => PARITY_TABLE[r as usize],
        LazyOp::Logic16(r) => PARITY_TABLE[(r & 0xFF) as usize],
        LazyOp::Logic32(r) => PARITY_TABLE[(r & 0xFF) as usize],
        LazyOp::Inc8 { r, .. } | LazyOp::Dec8 { r, .. } => PARITY_TABLE[r as usize],
        LazyOp::Inc16 { r, .. } | LazyOp::Dec16 { r, .. } => PARITY_TABLE[(r & 0xFF) as usize],
        LazyOp::Inc32 { r, .. } | LazyOp::Dec32 { r, .. } => PARITY_TABLE[(r & 0xFF) as usize],
        LazyOp::Shift8(r) => PARITY_TABLE[r as usize],
        LazyOp::Shift16(r) => PARITY_TABLE[(r & 0xFF) as usize],
        LazyOp::Shift32(r) => PARITY_TABLE[(r & 0xFF) as usize],
    }
}
/// Materialize all flags from lazy state into `flags_reg`, then reset to None.
#[inline(always)]
fn materialize_flags(flags_reg: &mut Flags, lazy: &mut LazyOp) {
    if matches!(*lazy, LazyOp::None) {
        return;
    }
    flags_reg.set(Flags::CARRY, get_cf(*flags_reg, lazy));
    flags_reg.set(Flags::ZERO, get_zf(*flags_reg, lazy));
    flags_reg.set(Flags::SIGN, get_sf(*flags_reg, lazy));
    flags_reg.set(Flags::OVERFLOW, get_of(*flags_reg, lazy));
    flags_reg.set(Flags::AUX_CARRY, get_af(*flags_reg, lazy));
    flags_reg.set(Flags::PARITY, get_pf(*flags_reg, lazy));
    *lazy = LazyOp::None;
}
/// P3-19: Materialize ZF, SF, AF, PF from lazy state, skipping CF and OF.
/// Use before instructions that set CF/OF themselves (MUL, IMUL, ROL, ROR).
#[inline(always)]
fn materialize_flags_skip_cf_of(flags_reg: &mut Flags, lazy: &mut LazyOp) {
    if matches!(*lazy, LazyOp::None) {
        return;
    }
    flags_reg.set(Flags::ZERO, get_zf(*flags_reg, lazy));
    flags_reg.set(Flags::SIGN, get_sf(*flags_reg, lazy));
    flags_reg.set(Flags::AUX_CARRY, get_af(*flags_reg, lazy));
    flags_reg.set(Flags::PARITY, get_pf(*flags_reg, lazy));
    *lazy = LazyOp::None;
}
/// Materialize all flags except CF — used by INC/DEC LoadCF pattern.
#[inline(always)]
fn save_cf_from_lazy(flags_reg: &mut Flags, lazy: &LazyOp) {
    let cf = get_cf(*flags_reg, lazy);
    flags_reg.set(Flags::CARRY, cf);
}
/// The shared hashed-TLB slot index (`SoftwareTlb::index`) — imported from
/// the memory crate, so the interpreter probes the slot the TLB fill wrote.
use gp64_memory_core::SoftwareTlb;
/// TLB fast-path read lookup via host pointer.
///
/// Returns a host pointer to the byte at `linear` if the TLB contains a valid
/// entry with appropriate permissions, or `None` on miss/permission failure.
/// VGA pages have null `host_read` so they always miss here.
///
/// # Safety
/// `tlb` must point to a valid TLB array of at least `TLB_SIZE` entries.
/// Returned host pointers derive from Memory::ram offsets set during TLB fill.
#[inline(always)]
unsafe fn tlb_translate_read(tlb: *const TlbEntry, linear: u32, cpl3: bool) -> Option<*const u8> {
    let page = linear >> 12;
    let idx = SoftwareTlb::index(page);
    let entry = &*tlb.add(idx);
    if entry.linear_page != page {
        return None;
    }
    if cpl3 && (entry.flags & TLB_FLAG_USER) == 0 {
        return None;
    }
    let ptr = entry.host_read;
    if ptr.is_null() {
        return None;
    }
    attrib::count_tlb_rd_hit();
    Some(ptr.add((linear & 0xFFF) as usize))
}
/// TLB fast-path write lookup via host pointer.
///
/// Returns a host pointer to the byte at `linear` if the TLB contains a valid,
/// writable, dirty entry with appropriate permissions, or `None` on miss.
/// VGA pages and read-only/non-dirty pages have null `host_write`.
///
/// # Safety
/// `tlb` must point to a valid TLB array of at least `TLB_SIZE` entries.
/// Returned host pointers derive from Memory::ram offsets set during TLB fill.
#[inline(always)]
unsafe fn tlb_translate_write(
    tlb: *const TlbEntry,
    linear: u32,
    cpl3: bool,
    wp_enabled: bool,
) -> Option<*mut u8> {
    let page = linear >> 12;
    let idx = SoftwareTlb::index(page);
    let entry = &*tlb.add(idx);
    if entry.linear_page != page {
        return None;
    }
    if cpl3 && (entry.flags & TLB_FLAG_USER) == 0 {
        return None;
    }
    if (entry.flags & TLB_FLAG_WRITABLE) == 0 && (cpl3 || wp_enabled) {
        return None;
    }
    if (entry.flags & TLB_FLAG_DIRTY) == 0 {
        return None;
    }
    let ptr = entry.host_write;
    if ptr.is_null() {
        return None;
    }
    attrib::count_tlb_wr_hit();
    Some(ptr.add((linear & 0xFFF) as usize))
}
/// TLB fast-path lookup returning a physical address (backward-compatible).
///
/// Retained for test code that expects `Option<usize>` physical addresses.
///
/// # Safety
/// `tlb` must point to a valid TLB array of at least `TLB_SIZE` entries.
#[cfg(test)]
#[inline(always)]
unsafe fn tlb_translate(
    tlb: *const TlbEntry,
    linear: u32,
    is_write: bool,
    cpl3: bool,
    wp_enabled: bool,
) -> Option<usize> {
    let page = linear >> 12;
    let idx = SoftwareTlb::index(page);
    let entry = &*tlb.add(idx);
    if entry.linear_page != page {
        return None;
    }
    let f = entry.flags;
    if is_write && (f & TLB_FLAG_WRITABLE) == 0 && (cpl3 || wp_enabled) {
        return None;
    }
    if cpl3 && (f & TLB_FLAG_USER) == 0 {
        return None;
    }
    if is_write && (f & TLB_FLAG_DIRTY) == 0 {
        return None;
    }
    Some(((entry.physical_page << 12) | (linear & 0xFFF)) as usize)
}
/// Slow-path paging translation: checks DPMI physical mappings, then does a
/// full page-table walk with permission checks and A/D bit updates.
#[cold]
#[inline(never)]
fn translate_slow<M: X86Machine>(
    cpu: &gp64_cpu::Cpu,
    mem: &mut M,
    linear: u32,
    access: gp64_types::PageAccess,
) -> Result<usize, gp64_cpu::PageFaultInfo> {
    #[inline(always)]
    fn apply_a20<M: X86Machine>(mem: &M, phys: usize) -> usize {
        M::phys_mask(mem.access_policy(), ArchPhys(phys)).0
    }
    if (cpu.regs.cr0 & 0x8000_0000) == 0 {
        if let Some(phys) = mem.map_linear_physical(linear) {
            return Ok(apply_a20(mem, phys));
        }
    }
    match cpu.translate_paging_checked(mem, linear, access) {
        Ok(phys) => Ok(apply_a20(mem, phys)),
        Err(pf) => {
            mem.set_page_fault(pf.linear_address, pf.error_code);
            Err(pf)
        }
    }
}
/// Cold function to build a #PF exception `RunResult`.
/// Restores IP to the faulting instruction start and materializes lazy flags.
#[cold]
#[inline(never)]
fn make_pf_exception(
    cpu: &mut gp64_cpu::Cpu,
    flags_reg: &mut Flags,
    lazy: &mut LazyOp,
    snap_ip: u32,
    pf: gp64_cpu::PageFaultInfo,
    executed: u32,
) -> RunResult {
    cpu.regs.set_eip(snap_ip);
    materialize_flags(flags_reg, lazy);
    cpu.regs.flags = *flags_reg;
    pf_trace_dump(pf.linear_address, snap_ip, cpu);
    RunResult::Exception {
        vector: 14,
        error_code: pf.error_code,
        fault_addr: Some(pf.linear_address),
        executed,
    }
}
/// Outlined slow path for paging read translation (TLB miss).
/// Called when `tlb_translate_read` returns `None`.  Performs the full page
/// walk and refreshes the caller's `ram` and `tlb` pointers on success.
#[cold]
#[inline(never)]
fn translate_read_miss<M: X86Machine>(
    cpu: &Cpu,
    mem: &mut M,
    ram: &mut *mut u8,
    tlb: &mut *const TlbEntry,
    linear: u32,
) -> Result<usize, PageFaultInfo> {
    attrib::count_tlb_rd_walk();
    let phys = translate_slow(cpu, mem, linear, gp64_types::PageAccess::Read)?;
    *ram = mem.core().ram_base_ptr();
    *tlb = mem.core().tlb_entries_ptr();
    Ok(phys)
}
/// Outlined slow path for paging write translation (TLB miss).
#[cold]
#[inline(never)]
fn translate_write_miss<M: X86Machine>(
    cpu: &Cpu,
    mem: &mut M,
    ram: &mut *mut u8,
    tlb: &mut *const TlbEntry,
    linear: u32,
) -> Result<usize, PageFaultInfo> {
    attrib::count_tlb_wr_walk();
    #[cfg(feature = "interp-attrib")]
    {
        let page = linear >> 12;
        let idx = SoftwareTlb::index(page);
        let tag_miss = unsafe { (*(*tlb).add(idx)).linear_page != page };
        attrib::count_wr_walk_pre(tag_miss);
    }
    {
        let page = linear >> 12;
        let idx = SoftwareTlb::index(page);
        let entry = unsafe { &*(*tlb).add(idx) };
        if entry.linear_page == page {
            let cpl3 = cpu.regs.cpl == 3;
            let wp_enabled = (cpu.regs.cr0 & 0x0001_0000) != 0;
            let user_ok = !cpl3 || (entry.flags & TLB_FLAG_USER) != 0;
            let writable_ok = (entry.flags & TLB_FLAG_WRITABLE) != 0 || !(cpl3 || wp_enabled);
            let dirty_ok = (entry.flags & TLB_FLAG_DIRTY) != 0;
            if user_ok && writable_ok && dirty_ok {
                debug_assert!(
                    entry.host_write.is_null(),
                    "flags-legal entry with a live host_write must have HIT the fast path"
                );
                mem.diag_count_tlb_device_reuse();
                return Ok(((entry.physical_page as usize) << 12) | (linear as usize & 0xFFF));
            }
        }
    }
    let phys_res = translate_slow(cpu, mem, linear, gp64_types::PageAccess::Write);
    attrib::count_wr_walk_dst(phys_res.as_ref().ok().copied());
    let phys = phys_res?;
    *ram = mem.core().ram_base_ptr();
    *tlb = mem.core().tlb_entries_ptr();
    Ok(phys)
}
/// Exception vector for a STRING-SOURCE segment-limit failure (`DS:SI`, or
/// whatever a segment-override prefix put in its place).
///
/// A limit fault is `#SS(12)` when the offending segment is SS and `#GP(13)`
/// otherwise — the same rule `check_seg_limit!` applies via its `__is_ss`,
/// and the reason the INITIAL per-instruction check already got this right.
/// The PER-ITERATION checks inside the REP loops of LODS, CMPS and MOVS
/// selected the overridden segment cache but then hardcoded 13
/// (MDD-BUG-CRUCIBLE-00660), so `REP LODS SS:[SI]` that faulted on the second
/// or later element reported `#GP(0)` where real hardware reports `#SS(0)`.
///
/// This is source-side only. The string DESTINATION is always `ES:DI` and
/// cannot be overridden, so destination limit failures stay `#GP` and must
/// not call this.
#[inline]
fn string_source_seg_fault_vector(seg_override: Option<u8>) -> u8 {
    if seg_override == Some(2) {
        12
    } else {
        13
    }
}
/// Outlined cold path for segment limit/access violation.
/// Materializes flags, restores IP, and returns the appropriate exception.
#[cold]
#[inline(never)]
fn make_seg_exception(
    cpu: &mut Cpu,
    flags_reg: &mut Flags,
    lazy: &mut LazyOp,
    snap_ip: u32,
    is_ss: bool,
    executed: u32,
) -> RunResult {
    cpu.regs.set_eip(snap_ip);
    materialize_flags(flags_reg, lazy);
    cpu.regs.flags = *flags_reg;
    RunResult::Exception {
        vector: if is_ss { 12 } else { 13 },
        error_code: 0,
        fault_addr: None,
        executed,
    }
}
/// A typed operand may use one translated address only while its bytes stay
/// contiguous. Paging splits at a page edge; with paging off, A20 splits
/// whenever the original linear span changes a masked address bit.
#[inline(always)]
fn operand_needs_byte_translation(linear: u32, width: u32, lin_mask: u32, paging: bool) -> bool {
    if paging {
        (linear & 0xFFF) + width > 0x1000
    } else {
        (linear ^ linear.wrapping_add(width - 1)) & !lin_mask != 0
    }
}
/// Outlined cold path for a u16 read across a page or A20 discontinuity.
///
/// # Safety
/// `*ram` must point to Memory::ram. Addresses are translated per-byte
/// through `translate_addr_read`, which validates each physical offset.
#[cold]
#[inline(never)]
unsafe fn read_u16_cross_page<M: X86Machine>(
    cpu: &Cpu,
    mem: &mut M,
    ram: &mut *mut u8,
    tlb: &mut *const TlbEntry,
    linear: u32,
    cpl3: bool,
    lin_mask: u32,
    paging: bool,
) -> Result<u16, PageFaultInfo> {
    let a0 = translate_addr_read(cpu, mem, ram, tlb, linear, cpl3, lin_mask, paging)?;
    let a1 = translate_addr_read(
        cpu,
        mem,
        ram,
        tlb,
        linear.wrapping_add(1),
        cpl3,
        lin_mask,
        paging,
    )?;
    let lo = vga_aware_read_u8((*ram).cast_const(), a0, mem) as u16;
    let hi = vga_aware_read_u8((*ram).cast_const(), a1, mem) as u16;
    Ok(lo | (hi << 8))
}
/// Outlined cold path for a u32 read across a page or A20 discontinuity.
///
/// # Safety
/// `*ram` must point to Memory::ram. Addresses are translated per-byte
/// through `translate_addr_read`, which validates each physical offset.
#[cold]
#[inline(never)]
unsafe fn read_u32_cross_page<M: X86Machine>(
    cpu: &Cpu,
    mem: &mut M,
    ram: &mut *mut u8,
    tlb: &mut *const TlbEntry,
    linear: u32,
    cpl3: bool,
    lin_mask: u32,
    paging: bool,
) -> Result<u32, PageFaultInfo> {
    let mut val = 0u32;
    for i in 0u32..4 {
        let a = translate_addr_read(
            cpu,
            mem,
            ram,
            tlb,
            linear.wrapping_add(i),
            cpl3,
            lin_mask,
            paging,
        )?;
        val |= (vga_aware_read_u8((*ram).cast_const(), a, mem) as u32) << (i * 8);
    }
    Ok(val)
}
/// Outlined cold path for a u16 write across a page or A20 discontinuity.
///
/// # Safety
/// `*ram` must point to Memory::ram. Addresses are translated per-byte
/// through `translate_addr_write`, which validates each physical offset.
#[cold]
#[inline(never)]
unsafe fn write_u16_cross_page<M: X86Machine>(
    cpu: &Cpu,
    mem: &mut M,
    ram: &mut *mut u8,
    tlb: &mut *const TlbEntry,
    linear: u32,
    val: u16,
    cpl3: bool,
    wp_enabled: bool,
    lin_mask: u32,
    paging: bool,
    guards: WriteGuards<M::AccessPolicy>,
) -> Result<(), PageFaultInfo> {
    let a0 = translate_addr_write(
        cpu, mem, ram, tlb, linear, cpl3, wp_enabled, lin_mask, paging,
    )?;
    let a1 = translate_addr_write(
        cpu,
        mem,
        ram,
        tlb,
        linear.wrapping_add(1),
        cpl3,
        wp_enabled,
        lin_mask,
        paging,
    )?;
    *ram = vga_aware_write_u8(*ram, a0, val as u8, mem, guards);
    *ram = vga_aware_write_u8(*ram, a1, (val >> 8) as u8, mem, guards);
    Ok(())
}
/// Outlined cold path for a u32 write across a page or A20 discontinuity.
///
/// # Safety
/// `*ram` must point to Memory::ram. Addresses are translated per-byte
/// through `translate_addr_write`, which validates each physical offset.
#[cold]
#[inline(never)]
unsafe fn write_u32_cross_page<M: X86Machine>(
    cpu: &Cpu,
    mem: &mut M,
    ram: &mut *mut u8,
    tlb: &mut *const TlbEntry,
    linear: u32,
    val: u32,
    cpl3: bool,
    wp_enabled: bool,
    lin_mask: u32,
    paging: bool,
    guards: WriteGuards<M::AccessPolicy>,
) -> Result<(), PageFaultInfo> {
    let bytes = val.to_le_bytes();
    let mut addrs = [0usize; 4];
    for (i, addr) in addrs.iter_mut().enumerate() {
        *addr = translate_addr_write(
            cpu,
            mem,
            ram,
            tlb,
            linear.wrapping_add(i as u32),
            cpl3,
            wp_enabled,
            lin_mask,
            paging,
        )?;
    }
    for (i, &a) in addrs.iter().enumerate() {
        *ram = vga_aware_write_u8(*ram, a, bytes[i], mem, guards);
    }
    Ok(())
}
/// Outlined cold path for a page-crossing 64-bit store.
///
/// All eight byte addresses are translated before any write so a fault on the
/// high page leaves the complete destination unchanged. Commits reuse the byte
/// router to preserve MMIO/VGA handling and every write observer.
///
/// # Safety
/// `*ram` must point to Memory::ram. Each physical address is validated by
/// `translate_addr_write` before it reaches `vga_aware_write_u8`.
#[cold]
#[inline(never)]
unsafe fn write_u64_cross_page<M: X86Machine>(
    cpu: &Cpu,
    mem: &mut M,
    ram: &mut *mut u8,
    tlb: &mut *const TlbEntry,
    linear: u32,
    val: u64,
    cpl3: bool,
    wp_enabled: bool,
    lin_mask: u32,
    paging: bool,
    guards: WriteGuards<M::AccessPolicy>,
) -> Result<(), PageFaultInfo> {
    let bytes = val.to_le_bytes();
    let mut addrs = [0usize; 8];
    for (index, addr) in addrs.iter_mut().enumerate() {
        *addr = translate_addr_write(
            cpu,
            mem,
            ram,
            tlb,
            linear.wrapping_add(index as u32),
            cpl3,
            wp_enabled,
            lin_mask,
            paging,
        )?;
    }
    for (index, &addr) in addrs.iter().enumerate() {
        *ram = vga_aware_write_u8(*ram, addr, bytes[index], mem, guards);
    }
    Ok(())
}
/// Helper: translate a linear address for reading (used by cross-page outlined functions).
#[inline(always)]
fn translate_addr_read<M: X86Machine>(
    cpu: &Cpu,
    mem: &mut M,
    ram: &mut *mut u8,
    tlb: &mut *const TlbEntry,
    linear: u32,
    cpl3: bool,
    lin_mask: u32,
    paging: bool,
) -> Result<usize, PageFaultInfo> {
    if paging {
        if let Some(ptr) = unsafe { tlb_translate_read(*tlb, linear, cpl3) } {
            Ok(ptr as usize - *ram as usize)
        } else {
            translate_read_miss(cpu, mem, ram, tlb, linear)
        }
    } else {
        Ok((linear & lin_mask) as usize)
    }
}
/// Helper: translate a linear address for writing (used by cross-page outlined functions).
#[inline(always)]
fn translate_addr_write<M: X86Machine>(
    cpu: &Cpu,
    mem: &mut M,
    ram: &mut *mut u8,
    tlb: &mut *const TlbEntry,
    linear: u32,
    cpl3: bool,
    wp_enabled: bool,
    lin_mask: u32,
    paging: bool,
) -> Result<usize, PageFaultInfo> {
    if paging {
        if let Some(ptr) = unsafe { tlb_translate_write(*tlb, linear, cpl3, wp_enabled) } {
            Ok(ptr as usize - *ram as usize)
        } else {
            translate_write_miss(cpu, mem, ram, tlb, linear)
        }
    } else {
        Ok((linear & lin_mask) as usize)
    }
}
/// Macro for concise page-fault error handling in opcode handlers.
/// On `Err(pf)`, restores IP and returns a #PF exception result.
#[allow(unused_macros)]
macro_rules! pf {
    ($result:expr) => {
        match $result {
            Ok(a) => a,
            Err(pf) => {
                return make_pf_exception(cpu, &mut flags_reg, &mut lazy, snap_ip, pf, executed);
            }
        }
    };
}
/// # Safety
/// `pos` must be in bounds for the allocation `ram` points to.
#[inline(always)]
unsafe fn read_u8_fast(ram: *const u8, pos: usize) -> u8 {
    *ram.add(pos)
}
/// # Safety
/// `pos..pos+2` must be in bounds for the allocation `ram` points to.
#[inline(always)]
unsafe fn read_u16_fast(ram: *const u8, pos: usize) -> u16 {
    (ram.add(pos) as *const u16).read_unaligned()
}
/// # Safety
/// `pos..pos+4` must be in bounds for the allocation `ram` points to.
#[inline(always)]
unsafe fn read_u32_fast(ram: *const u8, pos: usize) -> u32 {
    (ram.add(pos) as *const u32).read_unaligned()
}
/// # Safety
/// `pos` must be in bounds for the allocation `ram` points to.
#[inline(always)]
unsafe fn write_u8_fast(ram: *mut u8, pos: usize, val: u8) {
    *ram.add(pos) = val;
}
/// # Safety
/// `pos..pos+2` must be in bounds for the allocation `ram` points to.
#[inline(always)]
unsafe fn write_u16_fast(ram: *mut u8, pos: usize, val: u16) {
    (ram.add(pos) as *mut u16).write_unaligned(val);
}
/// # Safety
/// `pos..pos+4` must be in bounds for the allocation `ram` points to.
#[inline(always)]
unsafe fn write_u32_fast(ram: *mut u8, pos: usize, val: u32) {
    (ram.add(pos) as *mut u32).write_unaligned(val);
}
/// Hoisted write-path state, captured once at `run()` entry (R-AP1).
///
/// Bundling it avoids threading extra parameters through every
/// `vga_aware_write_*` call site (280+). It is `Copy` and small, so the
/// compiler keeps it in registers. The machine owns `policy` (its routing
/// and trace flags); the interpreter owns `diag` (M2 LLD §2.1-2.2).
#[derive(Clone, Copy)]
struct WriteGuards<P: AccessPolicyCore> {
    policy: P,
    diag: InterpDiag,
}
/// Interpreter-owned write diagnostics, captured beside the machine policy.
/// They gate on this crate's `EMU_PROBES`, which the machine cannot see.
///
/// One byte of flags, so `WriteGuards` stays within the register-passed
/// budget (M2 LLD §8 erratum 7).
#[derive(Clone, Copy, Default)]
struct InterpDiag(u8);
impl InterpDiag {
    const CAPTURE_WRITE_CONTEXT: u8 = 1 << 0;
    const WRITE_CONTEXT_DIAGNOSTIC: u8 = 1 << 1;
    #[inline(always)]
    fn new(capture_write_context: bool, write_context_diagnostic: bool) -> Self {
        InterpDiag(
            (u8::from(capture_write_context) * Self::CAPTURE_WRITE_CONTEXT)
                | (u8::from(write_context_diagnostic) * Self::WRITE_CONTEXT_DIAGNOSTIC),
        )
    }
    #[inline(always)]
    fn capture_write_context(self) -> bool {
        self.0 & Self::CAPTURE_WRITE_CONTEXT != 0
    }
    #[inline(always)]
    fn write_context_diagnostic(self) -> bool {
        self.0 & Self::WRITE_CONTEXT_DIAGNOSTIC != 0
    }
}
#[cfg(test)]
const _: () = assert!(std::mem::size_of::<WriteGuards<PcAccessPolicy>>() <= 8);
/// Test default: the policy of a fresh `Memory` (A20 open, no snoop, no
/// tracing, ROM writes dropped) and no diagnostics.
#[cfg(test)]
impl Default for WriteGuards<gp64_memory::PcAccessPolicy> {
    fn default() -> Self {
        WriteGuards {
            policy: gp64_memory::PcAccessPolicy {
                a20_enabled: true,
                smc_notifier: false,
                descriptor_snoop: false,
                write_tracking: false,
                traced_writes: false,
                allow_rom_writes: false,
            },
            diag: InterpDiag::default(),
        }
    }
}
/// VGA memory end address (exclusive).
#[cfg(test)]
const VGA_END: usize = VIDEO_BASE + 0x20000;
/// Test oracle helper: the PC EMS-frame overlap rule the pre-M2.2 funnels
/// applied inline (the machine's `write_prelude` owns it now).
#[cfg(test)]
#[inline(always)]
fn ems_frame_overlaps(mem: &Memory, addr: usize, len: usize) -> bool {
    len != 0
        && mem.hle_ems_frame_owned()
        && addr < EMS_FRAME_BASE + EMS_FRAME_SIZE
        && addr.saturating_add(len) > EMS_FRAME_BASE
}
#[inline(always)]
fn descriptor_snoop_active<M: X86Machine>(mem: &M, cached: bool) -> bool {
    cached || mem.core().has_descriptor_snoop()
}
/// Write a byte, routing it through the machine's write prelude.
///
/// Returns the (potentially refreshed) ram pointer.  Callers must assign
/// the return value back to their `ram` variable.
///
/// # Safety
/// `ram` must point to Memory::ram. The prelude bounds-checks `addr` against
/// usable_len() and the device ranges before the raw store.
#[inline]
unsafe fn vga_aware_write_u8<M: X86Machine>(
    ram: *mut u8,
    addr: usize,
    val: u8,
    mem: &mut M,
    guards: WriteGuards<M::AccessPolicy>,
) -> *mut u8 {
    attrib::count_mem_write(0);
    let p = guards.policy;
    let ram = match mem.write_prelude::<1>(p, GuestPhys(addr), val as u64) {
        WriteRoute::Raw => {
            if p.smc_notifier() {
                mem.smc_before_write(GuestPhys(addr), 1);
            }
            if descriptor_snoop_active(mem, p.descriptor_snoop()) {
                mem.snoop_descriptor_write(addr, val as u64, 1);
            }
            write_u8_fast(ram, addr, val);
            mem.write_epilogue::<1>(p, GuestPhys(addr), val as u64);
            ram
        }
        WriteRoute::Handled => ram,
        WriteRoute::HandledReload => mem.core().ram_base_ptr(),
        WriteRoute::Checked => mmio_write_u8_slow(mem, addr, val),
        WriteRoute::SplitBytes => unreachable!("byte stores never split"),
        WriteRoute::Dropped => return ram,
    };
    ram
}
/// Write a 16-bit word, routing it through the machine's write prelude.
///
/// # Safety
/// `ram` must point to Memory::ram. `addr` is bounds-checked before raw access.
#[inline]
unsafe fn vga_aware_write_u16<M: X86Machine>(
    ram: *mut u8,
    addr: usize,
    val: u16,
    mem: &mut M,
    guards: WriteGuards<M::AccessPolicy>,
) -> *mut u8 {
    attrib::count_mem_write(1);
    let p = guards.policy;
    let ram = match mem.write_prelude::<2>(p, GuestPhys(addr), val as u64) {
        WriteRoute::Raw => {
            if p.smc_notifier() {
                mem.smc_before_write(GuestPhys(addr), 2);
            }
            if descriptor_snoop_active(mem, p.descriptor_snoop()) {
                mem.snoop_descriptor_write(addr, val as u64, 2);
            }
            write_u16_fast(ram, addr, val);
            mem.write_epilogue::<2>(p, GuestPhys(addr), val as u64);
            ram
        }
        WriteRoute::Handled => ram,
        WriteRoute::HandledReload => mem.core().ram_base_ptr(),
        WriteRoute::Checked => mmio_write_u16_slow(mem, addr, val),
        WriteRoute::SplitBytes => {
            let mut ram = ram;
            for (i, byte) in val.to_le_bytes().iter().copied().enumerate() {
                ram = vga_aware_write_u8(ram, addr.wrapping_add(i), byte, mem, guards);
            }
            return ram;
        }
        WriteRoute::Dropped => return ram,
    };
    ram
}
