/// MMIO/VGA slow-path reader — `#[inline(never)]` prevents LTO from proving
/// the bounds check in `vga_aware_read_u8` dead and eliminating it.
#[cold]
#[inline(never)]
fn mmio_read_u8_slow<M: X86Machine>(mem: &M, addr: usize) -> u8 {
    mem.read_u8(addr)
}
#[cold]
#[inline(never)]
fn mmio_read_u16_slow<M: X86Machine>(mem: &M, addr: usize) -> u16 {
    mem.read_u16(addr)
}
#[cold]
#[inline(never)]
fn mmio_write_u8_slow<M: X86Machine>(mem: &mut M, addr: usize, val: u8) -> *mut u8 {
    mem.write_u8(addr, val);
    mem.core().ram_base_ptr()
}
#[cold]
#[inline(never)]
fn mmio_write_u16_slow<M: X86Machine>(mem: &mut M, addr: usize, val: u16) -> *mut u8 {
    mem.write_u16(addr, val);
    mem.core().ram_base_ptr()
}
#[cold]
#[inline(never)]
fn mmio_write_u32_slow<M: X86Machine>(mem: &mut M, addr: usize, val: u32) -> *mut u8 {
    mem.write_u32(addr, val);
    mem.core().ram_base_ptr()
}
#[inline(always)]
fn bulk_snoop_descriptor_range<M: X86Machine>(
    mem: &mut M,
    ram: *mut u8,
    start: usize,
    len: usize,
) -> *mut u8 {
    if len == 0 {
        return ram;
    }
    let end = start.saturating_add(len);
    let ranges = [
        (mem.core().gdt_snoop_base(), mem.core().gdt_snoop_end()),
        (mem.core().ldt_snoop_base(), mem.core().ldt_snoop_end()),
    ];
    let mut touched = false;
    for (range_start, range_end) in ranges {
        if range_end == 0 || start >= range_end || end <= range_start {
            continue;
        }
        let snoop_start = start.max(range_start);
        let snoop_end = end.min(range_end);
        for addr in snoop_start..snoop_end {
            let val = unsafe { *ram.add(addr) };
            mem.snoop_descriptor_write(addr, val as u64, 1);
        }
        touched = true;
    }
    if !touched {
        return ram;
    }
    mem.core().ram_base_ptr()
}
/// Read a byte, routing device-range reads through Memory (loads latches).
///
/// Does NOT require ram pointer refresh -- Memory::read_u8 takes &self.
///
/// # Safety
/// `ram` must point to Memory::ram. The prelude bounds-checks `addr` against
/// usable_len() and the device ranges before the raw load.
#[inline]
unsafe fn vga_aware_read_u8<M: X86Machine>(ram: *const u8, addr: usize, mem: &M) -> u8 {
    attrib::count_mem_read(0);
    match mem.read_prelude::<1>(GuestPhys(addr)) {
        ReadRoute::Raw => read_u8_fast(ram, addr),
        ReadRoute::Checked => mmio_read_u8_slow(mem, addr),
    }
}
/// Read a 16-bit word, routing device-range reads through Memory.
///
/// # Safety
/// `ram` must point to Memory::ram. `addr` is bounds-checked before raw access.
#[inline]
unsafe fn vga_aware_read_u16<M: X86Machine>(ram: *const u8, addr: usize, mem: &M) -> u16 {
    attrib::count_mem_read(1);
    match mem.read_prelude::<2>(GuestPhys(addr)) {
        ReadRoute::Raw => read_u16_fast(ram, addr),
        ReadRoute::Checked => mmio_read_u16_slow(mem, addr),
    }
}
/// Read a 32-bit dword, routing device-range reads through Memory.
///
/// # Safety
/// `ram` must point to Memory::ram. `addr` is bounds-checked before raw access.
#[inline]
unsafe fn vga_aware_read_u32<M: X86Machine>(ram: *const u8, addr: usize, mem: &M) -> u32 {
    attrib::count_mem_read(2);
    match mem.read_prelude::<4>(GuestPhys(addr)) {
        ReadRoute::Raw => read_u32_fast(ram, addr),
        ReadRoute::Checked => mem.read_u32(addr),
    }
}
/// Nonpaging stack and frame reads retain the original linear address so
/// clearing A20 on each byte preserves every other physical address bit.
///
/// # Safety
/// `ram` must point to Memory::ram; each access uses the machine read prelude.
#[inline]
unsafe fn read_nonpaged_operand<const W: usize, M: X86Machine>(
    ram: *const u8,
    linear: u32,
    lin_mask: u32,
    mem: &M,
) -> u32 {
    if operand_needs_byte_translation(linear, W as u32, lin_mask, false) {
        let mut value = 0;
        for i in 0..W {
            let addr = (linear.wrapping_add(i as u32) & lin_mask) as usize;
            value |= u32::from(vga_aware_read_u8(ram, addr, mem)) << (8 * i);
        }
        value
    } else {
        let addr = (linear & lin_mask) as usize;
        match W {
            2 => u32::from(vga_aware_read_u16(ram, addr, mem)),
            4 => vga_aware_read_u32(ram, addr, mem),
            _ => unreachable!("stack operands are words or dwords"),
        }
    }
}
/// Nonpaging stack writes use the same linear continuity rule as operands.
/// Every split byte retains the normal device and ROM write policy.
///
/// # Safety
/// `ram` must point to Memory::ram; each access uses the machine write prelude.
#[inline]
unsafe fn write_nonpaged_operand<const W: usize, M: X86Machine>(
    ram: *mut u8,
    linear: u32,
    lin_mask: u32,
    value: u32,
    mem: &mut M,
    guards: WriteGuards<M::AccessPolicy>,
) -> *mut u8 {
    if operand_needs_byte_translation(linear, W as u32, lin_mask, false) {
        let mut ram = ram;
        for i in 0..W {
            let addr = (linear.wrapping_add(i as u32) & lin_mask) as usize;
            ram = vga_aware_write_u8(ram, addr, (value >> (8 * i)) as u8, mem, guards);
        }
        ram
    } else {
        let addr = (linear & lin_mask) as usize;
        match W {
            2 => vga_aware_write_u16(ram, addr, value as u16, mem, guards),
            4 => vga_aware_write_u32(ram, addr, value, mem, guards),
            _ => unreachable!("stack operands are words or dwords"),
        }
    }
}
#[cfg(test)]
#[cfg_attr(coverage_nightly, coverage(off))]
mod machine_prelude_parity_tests;
/// Decode a 16-bit ModR/M memory address. Returns `(linear_addr, bytes_consumed)`.
/// `bytes_consumed` is the number of displacement bytes after the ModR/M byte.
///
/// `ds_base` and `ss_base` are the current segment bases (may be overridden by
/// a segment prefix). BP-based modes use ss_base; others use ds_base.
#[inline]
fn decode_modrm_addr16(
    cpu: &Cpu,
    fetch_base: *const u8,
    pos: usize,
    modrm: u8,
    ds_base: u32,
    ss_base: u32,
) -> (u32, u32, bool, usize) {
    let rm = modrm & 7;
    let md = (modrm >> 6) & 3;
    let (base, uses_bp) = match rm {
        0 => (cpu.regs.ebx.wrapping_add(cpu.regs.esi) as u16, false),
        1 => (cpu.regs.ebx.wrapping_add(cpu.regs.edi) as u16, false),
        2 => (cpu.regs.ebp.wrapping_add(cpu.regs.esi) as u16, true),
        3 => (cpu.regs.ebp.wrapping_add(cpu.regs.edi) as u16, true),
        4 => (cpu.regs.esi as u16, false),
        5 => (cpu.regs.edi as u16, false),
        6 => {
            if md == 0 {
                let disp = unsafe { read_u16_fast(fetch_base, pos) };
                let offset = disp as u32;
                return (offset, ds_base.wrapping_add(offset), false, 2);
            }
            (cpu.regs.ebp as u16, true)
        }
        7 => (cpu.regs.ebx as u16, false),
        _ => unreachable!(),
    };
    let seg = if uses_bp { ss_base } else { ds_base };
    match md {
        0 => {
            let offset = base as u32;
            (offset, seg.wrapping_add(offset), uses_bp, 0)
        }
        1 => {
            let disp = unsafe { read_u8_fast(fetch_base, pos) } as i8;
            let offset = (base as i16).wrapping_add(disp as i16) as u16 as u32;
            (offset, seg.wrapping_add(offset), uses_bp, 1)
        }
        2 => {
            let disp = unsafe { read_u16_fast(fetch_base, pos) };
            let offset = base.wrapping_add(disp) as u32;
            (offset, seg.wrapping_add(offset), uses_bp, 2)
        }
        _ => unreachable!(),
    }
}
/// Decode 32-bit ModR/M addressing (used when address-size is 32).
/// Returns `(offset, linear_address, uses_ss, bytes_consumed_after_modrm)`.
fn decode_modrm_addr32(
    cpu: &Cpu,
    fetch_base: *const u8,
    pos: usize,
    modrm: u8,
    ds_base: u32,
    ss_base: u32,
) -> (u32, u32, bool, usize) {
    let rm = modrm & 7;
    let md = (modrm >> 6) & 3;
    let reg32 = |idx: u8| -> u32 {
        match idx {
            0 => cpu.regs.eax,
            1 => cpu.regs.ecx,
            2 => cpu.regs.edx,
            3 => cpu.regs.ebx,
            4 => cpu.regs.esp,
            5 => cpu.regs.ebp,
            6 => cpu.regs.esi,
            7 => cpu.regs.edi,
            _ => 0,
        }
    };
    if rm == 4 {
        let sib = unsafe { read_u8_fast(fetch_base, pos) };
        let scale = 1u32 << ((sib >> 6) & 3);
        let idx = (sib >> 3) & 7;
        let base_reg = sib & 7;
        let index_val = if idx == 4 {
            0
        } else {
            reg32(idx).wrapping_mul(scale)
        };
        let (base_val, uses_bp, extra) = if base_reg == 5 && md == 0 {
            let disp = unsafe { read_u32_fast(fetch_base, pos + 1) };
            (disp, false, 5)
        } else {
            let uses_bp = base_reg == 4 || base_reg == 5;
            match md {
                0 => (reg32(base_reg), uses_bp, 1),
                1 => {
                    let disp = unsafe { read_u8_fast(fetch_base, pos + 1) } as i8 as i32 as u32;
                    (reg32(base_reg).wrapping_add(disp), uses_bp, 2)
                }
                2 => {
                    let disp = unsafe { read_u32_fast(fetch_base, pos + 1) };
                    (reg32(base_reg).wrapping_add(disp), uses_bp, 5)
                }
                _ => unreachable!(),
            }
        };
        let seg = if uses_bp { ss_base } else { ds_base };
        let offset = base_val.wrapping_add(index_val);
        (offset, seg.wrapping_add(offset), uses_bp, extra)
    } else {
        let uses_bp = rm == 5;
        match md {
            0 => {
                if rm == 5 {
                    let disp = unsafe { read_u32_fast(fetch_base, pos) };
                    (disp, ds_base.wrapping_add(disp), false, 4)
                } else {
                    let offset = reg32(rm);
                    (offset, ds_base.wrapping_add(offset), false, 0)
                }
            }
            1 => {
                let disp = unsafe { read_u8_fast(fetch_base, pos) } as i8 as i32 as u32;
                let seg = if uses_bp { ss_base } else { ds_base };
                let offset = reg32(rm).wrapping_add(disp);
                (offset, seg.wrapping_add(offset), uses_bp, 1)
            }
            2 => {
                let disp = unsafe { read_u32_fast(fetch_base, pos) };
                let seg = if uses_bp { ss_base } else { ds_base };
                let offset = reg32(rm).wrapping_add(disp);
                (offset, seg.wrapping_add(offset), uses_bp, 4)
            }
            _ => unreachable!(),
        }
    }
}
/// Dispatch to 16-bit or 32-bit ModR/M decoder based on address size.
/// Returns `(offset, linear_address, uses_ss, bytes_consumed_after_modrm)`.
///
/// The returned `linear_address` is a **true linear address** (seg_base + offset)
/// with NO A20 masking applied. The caller must apply `& lin_mask` at the point
/// of actual memory access to produce the physical address.
#[inline]
fn decode_modrm(
    cpu: &Cpu,
    fetch_base: *const u8,
    pos: usize,
    modrm: u8,
    ds_base: u32,
    ss_base: u32,
    addr_size_32: bool,
) -> (u32, u32, bool, usize) {
    if addr_size_32 {
        decode_modrm_addr32(cpu, fetch_base, pos, modrm, ds_base, ss_base)
    } else {
        decode_modrm_addr16(cpu, fetch_base, pos, modrm, ds_base, ss_base)
    }
}
/// P3-15: Precomputed `big_stack` flag eliminates `is_protected_mode()` call
/// in the push/pop hot path.  Computed once at `run()` entry, updated on
/// MOV SS / POP SS / LSS.
#[inline]
fn push16<M: X86Machine>(
    cpu: &mut Cpu,
    ram: *mut u8,
    ss_base: u32,
    val: u16,
    lin_mask: u32,
    big_stack: bool,
    mem: &mut M,
    guards: WriteGuards<M::AccessPolicy>,
) -> *mut u8 {
    if big_stack {
        cpu.regs.set_esp(cpu.regs.esp.wrapping_sub(2));
        let sp_after = cpu.regs.esp;
        let linear = ss_base.wrapping_add(sp_after);
        unsafe {
            write_nonpaged_operand::<2, _>(ram, linear, lin_mask, u32::from(val), mem, guards)
        }
    } else {
        let sp = cpu.regs.sp().wrapping_sub(2);
        let ram = if sp == 0xFFFF {
            let lo_addr = ss_base.wrapping_add(0xFFFF) & lin_mask;
            let hi_addr = ss_base.wrapping_add(0x0000) & lin_mask;
            let r = unsafe { vga_aware_write_u8(ram, lo_addr as usize, val as u8, mem, guards) };
            unsafe { vga_aware_write_u8(r, hi_addr as usize, (val >> 8) as u8, mem, guards) }
        } else {
            let linear = ss_base.wrapping_add(sp as u32);
            unsafe {
                write_nonpaged_operand::<2, _>(ram, linear, lin_mask, u32::from(val), mem, guards)
            }
        };
        cpu.regs.set_sp(sp);
        ram
    }
}
#[inline]
fn push32<M: X86Machine>(
    cpu: &mut Cpu,
    ram: *mut u8,
    ss_base: u32,
    val: u32,
    lin_mask: u32,
    big_stack: bool,
    mem: &mut M,
    guards: WriteGuards<M::AccessPolicy>,
) -> *mut u8 {
    if big_stack {
        cpu.regs.set_esp(cpu.regs.esp.wrapping_sub(4));
        let sp_after = cpu.regs.esp;
        let linear = ss_base.wrapping_add(sp_after);
        unsafe { write_nonpaged_operand::<4, _>(ram, linear, lin_mask, val, mem, guards) }
    } else {
        let sp = cpu.regs.sp().wrapping_sub(4);
        let ram = if sp > 0xFFFC {
            let bytes = val.to_le_bytes();
            let mut r = ram;
            for i in 0..4u16 {
                let off = sp.wrapping_add(i);
                let addr = ss_base.wrapping_add(off as u32) & lin_mask;
                r = unsafe { vga_aware_write_u8(r, addr as usize, bytes[i as usize], mem, guards) };
            }
            r
        } else {
            let linear = ss_base.wrapping_add(sp as u32);
            unsafe { write_nonpaged_operand::<4, _>(ram, linear, lin_mask, val, mem, guards) }
        };
        cpu.regs.set_sp(sp);
        ram
    }
}
#[inline]
fn pop16<M: X86Machine>(
    cpu: &mut Cpu,
    ram: *const u8,
    ss_base: u32,
    lin_mask: u32,
    big_stack: bool,
    mem: &M,
) -> u16 {
    if big_stack {
        let linear = ss_base.wrapping_add(cpu.regs.esp);
        let val = (unsafe { read_nonpaged_operand::<2, _>(ram, linear, lin_mask, mem) }) as u16;
        cpu.regs.set_esp(cpu.regs.esp.wrapping_add(2));
        val
    } else {
        let sp = cpu.regs.sp();
        let val = if sp == 0xFFFF {
            let lo_addr = ss_base.wrapping_add(0xFFFF) & lin_mask;
            let hi_addr = ss_base.wrapping_add(0x0000) & lin_mask;
            let lo = unsafe { vga_aware_read_u8(ram, lo_addr as usize, mem) } as u16;
            let hi = unsafe { vga_aware_read_u8(ram, hi_addr as usize, mem) } as u16;
            lo | (hi << 8)
        } else {
            let linear = ss_base.wrapping_add(sp as u32);
            (unsafe { read_nonpaged_operand::<2, _>(ram, linear, lin_mask, mem) }) as u16
        };
        let new_sp = sp.wrapping_add(2);
        cpu.regs.set_sp(new_sp);
        val
    }
}
#[inline]
fn pop32<M: X86Machine>(
    cpu: &mut Cpu,
    ram: *const u8,
    ss_base: u32,
    lin_mask: u32,
    big_stack: bool,
    mem: &M,
) -> u32 {
    if big_stack {
        let linear = ss_base.wrapping_add(cpu.regs.esp);
        let val = unsafe { read_nonpaged_operand::<4, _>(ram, linear, lin_mask, mem) };
        cpu.regs.set_esp(cpu.regs.esp.wrapping_add(4));
        val
    } else {
        let sp = cpu.regs.sp();
        let val = if sp > 0xFFFC {
            let mut v = 0u32;
            for i in 0..4u16 {
                let off = sp.wrapping_add(i);
                let addr = ss_base.wrapping_add(off as u32) & lin_mask;
                v |= (unsafe { vga_aware_read_u8(ram, addr as usize, mem) } as u32) << (i * 8);
            }
            v
        } else {
            let linear = ss_base.wrapping_add(sp as u32);
            unsafe { read_nonpaged_operand::<4, _>(ram, linear, lin_mask, mem) }
        };
        let new_sp = sp.wrapping_add(4);
        cpu.regs.set_sp(new_sp);
        val
    }
}
/// Translate a linear address for write via TLB fast path / slow page walk.
/// Returns physical address on success, `Err(PageFaultInfo)` on fault.
/// Updates `ram` and `tlb` if a slow-path walk occurs (it may reallocate).
#[inline]
fn translate_write_stack<M: X86Machine>(
    cpu: &Cpu,
    mem: &mut M,
    linear: u32,
    tlb: *const TlbEntry,
    cpl3: bool,
    wp_enabled: bool,
    ram: *mut u8,
) -> Result<(usize, *mut u8, *const TlbEntry), PageFaultInfo> {
    if let Some(ptr) = unsafe { tlb_translate_write(tlb, linear, cpl3, wp_enabled) } {
        Ok((ptr as usize - ram as usize, ram, tlb))
    } else {
        match translate_slow(cpu, mem, linear, gp64_types::PageAccess::Write) {
            Ok(phys) => Ok((
                phys,
                mem.core().ram_base_ptr(),
                mem.core().tlb_entries_ptr(),
            )),
            Err(pf) => Err(pf),
        }
    }
}
/// Translate a linear address for read via TLB fast path / slow page walk.
#[inline]
fn translate_read_stack<M: X86Machine>(
    cpu: &Cpu,
    mem: &mut M,
    linear: u32,
    tlb: *const TlbEntry,
    cpl3: bool,
    _wp_enabled: bool,
    ram: *const u8,
) -> Result<(usize, *const u8, *const TlbEntry), PageFaultInfo> {
    if let Some(ptr) = unsafe { tlb_translate_read(tlb, linear, cpl3) } {
        Ok((ptr as usize - ram as usize, ram, tlb))
    } else {
        match translate_slow(cpu, mem, linear, gp64_types::PageAccess::Read) {
            Ok(phys) => {
                let new_ram = mem.core().ram_base_ptr().cast_const();
                Ok((phys, new_ram, mem.core().tlb_entries_ptr()))
            }
            Err(pf) => Err(pf),
        }
    }
}
/// MDD-BUG-CRUCIBLE-00331: warm a cold paging TLB entry and RETRY the bulk
/// chunk, instead of abandoning the bulk loop for the whole remaining slice.
///
/// A miss in the page-at-a-time REP STOS/MOVS loops is usually an ORDINARY
/// cold or clean entry: the page is mapped and is ordinary RAM, the hashed TLB
/// simply has no (dirty) entry for it yet. The old `None => break` handed the
/// entire residual REP to the per-element loop, which warms the page on its
/// first element but never returns to the bulk path — so a multi-kilobyte REP
/// onto a freshly mapped page paid per-element translation and guard cost for
/// all of it, losing the intended O(pages) route.
///
/// `$warmed` is the no-progress guard the record asks for: each page is warmed
/// AT MOST once, so a page that still misses after its own walk is not an
/// ordinary miss (fault, MMIO, non-RAM, permission) and drops to the
/// per-element loop exactly as before. Every other bail in these loops — VGA
/// range, segment limit, non-`direct_host_ram_range`, reverse direction — is
/// untouched.
///
/// On a FAULTING walk we `break` without raising here. The per-element loop
/// redoes the same access and raises the fault with the architectural CX/EIP
/// state, which is the only place that state is assembled correctly; raising
/// from inside the bulk loop would report a mid-chunk CX.
/// MDD-BUG-CRUCIBLE-00331 regression instrument: counts paged REP bulk chunks
/// committed.
///
/// Test-only, and it has to exist: the bulk and per-element routes leave guest
/// memory and registers IDENTICAL — they differ only in how much translation
/// and guard work was paid to get there. So "did the bulk path resume after a
/// cold miss?" is not observable from architectural state, and counting
/// committed chunks is the only way to pin the fix.
#[cfg(test)]
static PAGED_REP_BULK_CHUNKS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
#[cfg(test)]
fn paged_rep_bulk_chunks_reset() {
    PAGED_REP_BULK_CHUNKS.store(0, Ordering::Relaxed);
}
#[cfg(test)]
fn paged_rep_bulk_chunks() -> u64 {
    PAGED_REP_BULK_CHUNKS.load(Ordering::Relaxed)
}
#[cfg(test)]
#[inline]
fn paged_rep_bulk_chunk_observed() {
    PAGED_REP_BULK_CHUNKS.fetch_add(1, Ordering::Relaxed);
}
/// Zero-cost in every real build.
#[cfg(not(test))]
#[inline(always)]
fn paged_rep_bulk_chunk_observed() {}
macro_rules! warm_bulk_tlb_or_break {
    (
        $cpu:expr, $mem:expr, $ram:ident, $tlb:ident, $lin:expr, $access:expr,
        $warmed:ident
    ) => {{
        let __page = $lin >> 12;
        if $warmed == Some(__page) {
            break;
        }
        $warmed = Some(__page);
        if translate_slow($cpu, $mem, $lin, $access).is_err() {
            break;
        }
        $ram = $mem.core().ram_base_ptr();
        $tlb = $mem.core().tlb_entries_ptr();
        continue;
    }};
}
/// Commit the new stack pointer after a push/pop, preserving ESP high word
/// for 16-bit stacks.
#[inline(always)]
fn commit_sp(cpu: &mut Cpu, new_sp: u32, big_stack: bool) {
    if big_stack {
        cpu.regs.esp = new_sp;
        cpu.regs.set_sp(new_sp as u16);
    } else {
        let sp16 = new_sp as u16;
        cpu.regs.set_sp(sp16);
    }
}
/// Paging-aware PUSH u16.  Translates the stack address BEFORE committing SP.
/// On page fault, SP is unchanged and `Err(PageFaultInfo)` is returned.
/// Cross-page pushes (straddling a 4 KB boundary) are decomposed into per-byte
/// writes with independent translations.
#[inline]
fn push16_paged<M: X86Machine>(
    cpu: &mut Cpu,
    ram: *mut u8,
    ss_base: u32,
    val: u16,
    big_stack: bool,
    mem: &mut M,
    tlb: *const TlbEntry,
    cpl3: bool,
    wp_enabled: bool,
    guards: WriteGuards<M::AccessPolicy>,
) -> Result<(*mut u8, *const TlbEntry), PageFaultInfo> {
    let new_sp = if big_stack {
        cpu.regs.esp.wrapping_sub(2)
    } else {
        cpu.regs.sp().wrapping_sub(2) as u32
    };
    let seg_wrap = !big_stack && (new_sp as u16) == 0xFFFF;
    let linear0 = ss_base.wrapping_add(new_sp);
    let linear1 = if seg_wrap {
        ss_base
    } else {
        linear0.wrapping_add(1)
    };
    if seg_wrap || (linear0 & 0xFFF) + 2 > 0x1000 {
        let (a0, ram, tlb) = translate_write_stack(cpu, mem, linear0, tlb, cpl3, wp_enabled, ram)?;
        let (a1, ram, tlb) = translate_write_stack(cpu, mem, linear1, tlb, cpl3, wp_enabled, ram)?;
        commit_sp(cpu, new_sp, big_stack);
        let ram = unsafe { vga_aware_write_u8(ram, a0, val as u8, mem, guards) };
        let ram = unsafe { vga_aware_write_u8(ram, a1, (val >> 8) as u8, mem, guards) };
        Ok((ram, tlb))
    } else {
        let (addr, ram, tlb) =
            translate_write_stack(cpu, mem, linear0, tlb, cpl3, wp_enabled, ram)?;
        maybe_trace_stack_linear_access("write", cpu, linear0, addr, 2, val as u64);
        commit_sp(cpu, new_sp, big_stack);
        let ram = unsafe { vga_aware_write_u16(ram, addr, val, mem, guards) };
        Ok((ram, tlb))
    }
}
/// Paging-aware PUSH u32.  Same translate-before-commit semantics as push16_paged.
#[inline]
fn push32_paged<M: X86Machine>(
    cpu: &mut Cpu,
    ram: *mut u8,
    ss_base: u32,
    val: u32,
    big_stack: bool,
    mem: &mut M,
    tlb: *const TlbEntry,
    cpl3: bool,
    wp_enabled: bool,
    guards: WriteGuards<M::AccessPolicy>,
) -> Result<(*mut u8, *const TlbEntry), PageFaultInfo> {
    let new_sp = if big_stack {
        cpu.regs.esp.wrapping_sub(4)
    } else {
        cpu.regs.sp().wrapping_sub(4) as u32
    };
    let seg_wrap = !big_stack && (new_sp as u16) > 0xFFFC;
    let linear0 = ss_base.wrapping_add(new_sp);
    if seg_wrap || (linear0 & 0xFFF) + 4 > 0x1000 {
        let bytes = val.to_le_bytes();
        let mut ram = ram;
        let mut tlb = tlb;
        let mut addrs = [0usize; 4];
        for i in 0..4u32 {
            let stack_off = if big_stack {
                new_sp.wrapping_add(i)
            } else {
                (new_sp as u16).wrapping_add(i as u16) as u32
            };
            let lin = ss_base.wrapping_add(stack_off);
            let (a, new_ram, new_tlb) =
                translate_write_stack(cpu, mem, lin, tlb, cpl3, wp_enabled, ram)?;
            addrs[i as usize] = a;
            ram = new_ram;
            tlb = new_tlb;
        }
        commit_sp(cpu, new_sp, big_stack);
        let ram = unsafe { vga_aware_write_u8(ram, addrs[0], bytes[0], mem, guards) };
        let ram = unsafe { vga_aware_write_u8(ram, addrs[1], bytes[1], mem, guards) };
        let ram = unsafe { vga_aware_write_u8(ram, addrs[2], bytes[2], mem, guards) };
        let ram = unsafe { vga_aware_write_u8(ram, addrs[3], bytes[3], mem, guards) };
        Ok((ram, tlb))
    } else {
        let (addr, ram, tlb) =
            translate_write_stack(cpu, mem, linear0, tlb, cpl3, wp_enabled, ram)?;
        maybe_trace_stack_linear_access("write", cpu, linear0, addr, 4, val as u64);
        commit_sp(cpu, new_sp, big_stack);
        let ram = unsafe { vga_aware_write_u32(ram, addr, val, mem, guards) };
        Ok((ram, tlb))
    }
}
/// Paging-aware POP u16.  Translates the stack address BEFORE committing SP.
/// On page fault, SP is unchanged and `Err(PageFaultInfo)` is returned.
#[inline]
fn pop16_paged<M: X86Machine>(
    cpu: &mut Cpu,
    ram: *const u8,
    ss_base: u32,
    big_stack: bool,
    mem: &mut M,
    tlb: *const TlbEntry,
    cpl3: bool,
    wp_enabled: bool,
) -> Result<(u16, *const u8, *const TlbEntry), PageFaultInfo> {
    let sp = if big_stack {
        cpu.regs.esp
    } else {
        cpu.regs.sp() as u32
    };
    let seg_wrap = !big_stack && (sp as u16) == 0xFFFF;
    let linear0 = ss_base.wrapping_add(sp);
    let linear1 = if seg_wrap {
        ss_base
    } else {
        linear0.wrapping_add(1)
    };
    if seg_wrap || (linear0 & 0xFFF) + 2 > 0x1000 {
        let (a0, ram, tlb) = translate_read_stack(cpu, mem, linear0, tlb, cpl3, wp_enabled, ram)?;
        let (a1, ram, tlb) = translate_read_stack(cpu, mem, linear1, tlb, cpl3, wp_enabled, ram)?;
        let lo = unsafe { vga_aware_read_u8(ram, a0, mem) } as u16;
        let hi = unsafe { vga_aware_read_u8(ram, a1, mem) } as u16;
        let val = lo | (hi << 8);
        let new_sp = sp.wrapping_add(2);
        commit_sp(cpu, new_sp, big_stack);
        Ok((val, ram, tlb))
    } else {
        let (addr, ram, tlb) = translate_read_stack(cpu, mem, linear0, tlb, cpl3, wp_enabled, ram)?;
        let val = unsafe { vga_aware_read_u16(ram, addr, mem) };
        maybe_trace_stack_linear_access("read", cpu, linear0, addr, 2, val as u64);
        let new_sp = sp.wrapping_add(2);
        commit_sp(cpu, new_sp, big_stack);
        Ok((val, ram, tlb))
    }
}
/// Paging-aware POP u32.  Same translate-before-commit semantics as pop16_paged.
#[inline]
fn pop32_paged<M: X86Machine>(
    cpu: &mut Cpu,
    ram: *const u8,
    ss_base: u32,
    big_stack: bool,
    mem: &mut M,
    tlb: *const TlbEntry,
    cpl3: bool,
    wp_enabled: bool,
) -> Result<(u32, *const u8, *const TlbEntry), PageFaultInfo> {
    let sp = if big_stack {
        cpu.regs.esp
    } else {
        cpu.regs.sp() as u32
    };
    let seg_wrap = !big_stack && (sp as u16) > 0xFFFC;
    let linear0 = ss_base.wrapping_add(sp);
    if seg_wrap || (linear0 & 0xFFF) + 4 > 0x1000 {
        let mut val = 0u32;
        let mut ram = ram;
        let mut tlb = tlb;
        for i in 0..4u32 {
            let stack_off = if big_stack {
                sp.wrapping_add(i)
            } else {
                (sp as u16).wrapping_add(i as u16) as u32
            };
            let lin = ss_base.wrapping_add(stack_off);
            let (a, new_ram, new_tlb) =
                translate_read_stack(cpu, mem, lin, tlb, cpl3, wp_enabled, ram)?;
            ram = new_ram;
            tlb = new_tlb;
            val |= (unsafe { vga_aware_read_u8(ram, a, mem) } as u32) << (i * 8);
        }
        let new_sp = sp.wrapping_add(4);
        commit_sp(cpu, new_sp, big_stack);
        Ok((val, ram, tlb))
    } else {
        let (addr, ram, tlb) = translate_read_stack(cpu, mem, linear0, tlb, cpl3, wp_enabled, ram)?;
        let val = unsafe { vga_aware_read_u32(ram, addr, mem) };
        maybe_trace_stack_linear_access("read", cpu, linear0, addr, 4, val as u64);
        let new_sp = sp.wrapping_add(4);
        commit_sp(cpu, new_sp, big_stack);
        Ok((val, ram, tlb))
    }
}
/// Nullify data segment registers (DS, ES, FS, GS) whose DPL is less than
/// the new CPL after a privilege-changing far return or IRET.  This prevents
/// the outer-ring code from retaining access to inner-ring data segments.
#[inline]
fn retf_nullify_segments(cpu: &mut Cpu, new_cpl: u8) {
    if cpu.regs.ds != 0 && cpu.regs.ds_cache.dpl < new_cpl {
        cpu.regs.ds = 0;
        cpu.regs.ds_cache = SegmentCache::default();
    }
    if cpu.regs.es != 0 && cpu.regs.es_cache.dpl < new_cpl {
        cpu.regs.es = 0;
        cpu.regs.es_cache = SegmentCache::default();
    }
    if cpu.regs.fs != 0 && cpu.regs.fs_cache.dpl < new_cpl {
        cpu.regs.fs = 0;
        cpu.regs.fs_cache = SegmentCache::default();
    }
    if cpu.regs.gs != 0 && cpu.regs.gs_cache.dpl < new_cpl {
        cpu.regs.gs = 0;
        cpu.regs.gs_cache = SegmentCache::default();
    }
}
/// Evaluate a condition code (0-15) against lazy flags.
/// Returns true if the condition is met.
#[inline(always)]
fn eval_cc(flags_reg: Flags, lazy: &LazyOp, cc: u8) -> bool {
    match cc & 0xF {
        0x0 => get_of(flags_reg, lazy),
        0x1 => !get_of(flags_reg, lazy),
        0x2 => get_cf(flags_reg, lazy),
        0x3 => !get_cf(flags_reg, lazy),
        0x4 => get_zf(flags_reg, lazy),
        0x5 => !get_zf(flags_reg, lazy),
        0x6 => get_cf(flags_reg, lazy) || get_zf(flags_reg, lazy),
        0x7 => !get_cf(flags_reg, lazy) && !get_zf(flags_reg, lazy),
        0x8 => get_sf(flags_reg, lazy),
        0x9 => !get_sf(flags_reg, lazy),
        0xA => get_pf(flags_reg, lazy),
        0xB => !get_pf(flags_reg, lazy),
        0xC => get_sf(flags_reg, lazy) != get_of(flags_reg, lazy),
        0xD => get_sf(flags_reg, lazy) == get_of(flags_reg, lazy),
        0xE => get_zf(flags_reg, lazy) || (get_sf(flags_reg, lazy) != get_of(flags_reg, lazy)),
        0xF => !get_zf(flags_reg, lazy) && (get_sf(flags_reg, lazy) == get_of(flags_reg, lazy)),
        _ => unreachable!(),
    }
}
/// Perform an 8-bit ALU operation identified by `base` (the opcode base: 0x00=ADD,
/// 0x08=OR, 0x20=AND, 0x28=SUB, 0x30=XOR, 0x38=CMP). Returns `(result, lazy_op)`.
#[inline(always)]
fn alu8(base: u8, a: u8, b: u8) -> (u8, LazyOp) {
    match base {
        0x00 => {
            let r = a.wrapping_add(b);
            (r, LazyOp::Add8 { a, b, r })
        }
        0x08 => {
            let r = a | b;
            (r, LazyOp::Logic8(r))
        }
        0x20 => {
            let r = a & b;
            (r, LazyOp::Logic8(r))
        }
        0x28 | 0x38 => {
            let r = a.wrapping_sub(b);
            (r, LazyOp::Sub8 { a, b, r })
        }
        0x30 => {
            let r = a ^ b;
            (r, LazyOp::Logic8(r))
        }
        _ => unreachable!(),
    }
}
/// Perform a 16-bit ALU operation. Same convention as `alu8`.
#[inline(always)]
fn alu16(base: u8, a: u16, b: u16) -> (u16, LazyOp) {
    match base {
        0x00 => {
            let r = a.wrapping_add(b);
            (r, LazyOp::Add16 { a, b, r })
        }
        0x08 => {
            let r = a | b;
            (r, LazyOp::Logic16(r))
        }
        0x20 => {
            let r = a & b;
            (r, LazyOp::Logic16(r))
        }
        0x28 | 0x38 => {
            let r = a.wrapping_sub(b);
            (r, LazyOp::Sub16 { a, b, r })
        }
        0x30 => {
            let r = a ^ b;
            (r, LazyOp::Logic16(r))
        }
        _ => unreachable!(),
    }
}
/// Perform a 32-bit ALU operation. Same convention as `alu8`.
#[inline(always)]
fn alu32(base: u8, a: u32, b: u32) -> (u32, LazyOp) {
    match base {
        0x00 => {
            let r = a.wrapping_add(b);
            (r, LazyOp::Add32 { a, b, r })
        }
        0x08 => {
            let r = a | b;
            (r, LazyOp::Logic32(r))
        }
        0x20 => {
            let r = a & b;
            (r, LazyOp::Logic32(r))
        }
        0x28 | 0x38 => {
            let r = a.wrapping_sub(b);
            (r, LazyOp::Sub32 { a, b, r })
        }
        0x30 => {
            let r = a ^ b;
            (r, LazyOp::Logic32(r))
        }
        _ => unreachable!(),
    }
}
/// ADC 8-bit: result = a + b + cf. Eagerly sets all flags.
#[inline]
fn adc8(flags: &mut Flags, a: u8, b: u8, cf: bool) -> u8 {
    let c = cf as u16;
    let temp = (a as u16) + (b as u16) + c;
    let r = temp as u8;
    flags.set(Flags::CARRY, temp > 0xFF);
    flags.set(Flags::OVERFLOW, ((a ^ r) & (b ^ r) & 0x80) != 0);
    flags.set(Flags::AUX_CARRY, ((a ^ b ^ r) & 0x10) != 0);
    flags.set(Flags::SIGN, r & 0x80 != 0);
    flags.set(Flags::ZERO, r == 0);
    flags.set(Flags::PARITY, PARITY_TABLE[r as usize]);
    r
}
