/// Perform 8-bit shift/rotate. Returns result. Flags set on cpu.regs.flags.
/// `sub_op`: 0=ROL,1=ROR,2=RCL,3=RCR,4=SHL,5=SHR,6=SAL(=SHL),7=SAR
#[inline]
fn shift8(cpu: &mut Cpu, val: u8, count: u8, sub_op: u8) -> u8 {
    let count = (count & 0x1F) as u32;
    if count == 0 {
        return val;
    }
    let flags = &mut cpu.regs.flags;
    match sub_op {
        4 | 6 => {
            let r = if count >= 8 { 0u8 } else { val << count };
            let cf = shl8_carry(val, count);
            flags.set(Flags::CARRY, cf);
            if count == 1 {
                flags.set(Flags::OVERFLOW, (r & 0x80 != 0) != cf);
            }
            set_szp8(flags, r);
            r
        }
        5 => {
            let r = if count >= 8 { 0u8 } else { val >> count };
            let cf = shr8_carry(val, count);
            flags.set(Flags::CARRY, cf);
            if count == 1 {
                flags.set(Flags::OVERFLOW, val & 0x80 != 0);
            }
            set_szp8(flags, r);
            r
        }
        7 => {
            let cnt = count.min(8);
            let r = ((val as i8) >> cnt.min(7)) as u8;
            let cf = val & (1 << (cnt.min(8) - 1)) != 0;
            flags.set(Flags::CARRY, cf);
            if count == 1 {
                flags.remove(Flags::OVERFLOW);
            }
            set_szp8(flags, r);
            r
        }
        0 => {
            let cnt = count & 7;
            if cnt == 0 {
                flags.set(Flags::CARRY, val & 1 != 0);
                return val;
            }
            let r = val.rotate_left(cnt);
            flags.set(Flags::CARRY, r & 1 != 0);
            if count == 1 {
                flags.set(Flags::OVERFLOW, (r & 0x80 != 0) != (r & 1 != 0));
            }
            r
        }
        1 => {
            let cnt = count & 7;
            if cnt == 0 {
                flags.set(Flags::CARRY, val & 0x80 != 0);
                return val;
            }
            let r = val.rotate_right(cnt);
            flags.set(Flags::CARRY, r & 0x80 != 0);
            if count == 1 {
                flags.set(Flags::OVERFLOW, (r & 0x80 != 0) != (r & 0x40 != 0));
            }
            r
        }
        2 => {
            let cnt = count % 9;
            if cnt == 0 {
                return val;
            }
            let cf_in = flags.contains(Flags::CARRY) as u16;
            let wide = (val as u16) | (cf_in << 8);
            let rotated = (wide << cnt) | (wide >> (9 - cnt));
            let r = rotated as u8;
            flags.set(Flags::CARRY, rotated & 0x100 != 0);
            if count == 1 {
                flags.set(
                    Flags::OVERFLOW,
                    (r & 0x80 != 0) != flags.contains(Flags::CARRY),
                );
            }
            r
        }
        3 => {
            let cnt = count % 9;
            if cnt == 0 {
                return val;
            }
            let cf_in = flags.contains(Flags::CARRY) as u16;
            if count == 1 {
                flags.set(Flags::OVERFLOW, (val & 0x80 != 0) != (cf_in != 0));
            }
            let wide = (val as u16) | (cf_in << 8);
            let rotated = (wide >> cnt) | (wide << (9 - cnt));
            let r = rotated as u8;
            flags.set(Flags::CARRY, rotated & 0x100 != 0);
            r
        }
        _ => unreachable!(),
    }
}
