            let cnt = count & 15;
            if cnt == 0 {
                flags.set(Flags::CARRY, val & 0x8000 != 0);
                return val;
            }
            let r = val.rotate_right(cnt);
            flags.set(Flags::CARRY, r & 0x8000 != 0);
