                cpu.regs.set_eip(ip_val);
                cpu.regs.flags = flags_reg;
                out.flags = flags_reg;
                out.lazy = LazyOp::None;
                return ArmFlow::Return(RunResult::Exception {
                    vector,
                    error_code,
                    fault_addr,
                    executed: *executed,
                });
