                    cpu.regs.cs_cache = saved_cs_cache;
                    cpu.regs.set_cpl(saved_cpl);
                    cpu.cs_bits = saved_cs_bits;
                    cpu.regs.esp = saved_esp;
                    cpu.regs.set_sp(saved_sp);
                    cpu.regs.set_eip(ip_val);
                    cpu.last_exception_error_code = 0;
