            let mut masked = (fetch_linear & lin_mask) as usize;
            masked = mem.fetch_alias(GuestPhys(masked)).0;
            if fetch_is_open_bus(mem, masked, ram_len, 15) {
                if !PHYS_OOB_FETCH_NOPAGING_WARNED.swap(true, Ordering::Relaxed) {
                    tracing::warn!(
                        target : "gp64::interp::fetch",
                        "phys-OOB fetch (no paging): linear=0x{:08X} masked=0x{:08X} ram_len=0x{:08X} cs=0x{:04X} eip=0x{:08X}; returning open-bus (0xFF). Subsequent occurrences silenced.",
                        fetch_linear, masked, ram_len, cpu.regs.cs, ip_val
                    );
                }
                unsafe {
                    ptr::write_bytes(fetch_buf.as_mut_ptr(), 0xFF, 32);
                }
                pos = 0;
                fetch_base = fetch_buf.as_ptr();
            } else if mem
                .direct_span(GuestPhys(masked), 15, AccessIntent::Fetch)
                .is_some()
            {
                pos = masked;
                fetch_base = ram.cast_const();
            } else {
                mem.fetch_checked(GuestPhys(masked), &mut fetch_buf);
                pos = 0;
                fetch_base = fetch_buf.as_ptr();
            }
